}

fn fano_line_k(n: i32) -> i32 {
    if n == 0 { return 3 }
    if n == 1 { return 5 }
    if n == 2 { return 6 }
    if n == 3 { return 6 }
    if n == 4 { return 7 }
    if n == 5 { return 7 }
