// Extract 7 eigenvectors of C8 Laplacian
fn c8_extract_eigenvectors() -> Evecs7 with Mut {
    let mut result = Evecs7 {
        e0: vec8_zero(), e1: vec8_zero(), e2: vec8_zero(), e3: vec8_zero(),
        e4: vec8_zero(), e5: vec8_zero(), e6: vec8_zero(),
        l0: 0.0, l1: 0.0, l2: 0.0, l3: 0.0, l4: 0.0, l5: 0.0, l6: 0.0,
    }

    let mut ek: i32 = 0
    while ek < 7 {
        // Initialize with different starting vectors
        let mut v = vec8_zero()
        if ek == 0 { v = Vec8 { v0: 1.0, v1: 0.0-1.0, v2: 1.0, v3: 0.0-1.0, v4: 1.0, v5: 0.0-1.0, v6: 1.0, v7: 0.0-1.0 } }
        if ek == 1 { v = Vec8 { v0: 1.0, v1: 1.0, v2: 0.0-1.0, v3: 0.0-1.0, v4: 1.0, v5: 1.0, v6: 0.0-1.0, v7: 0.0-1.0 } }
        if ek == 2 { v = Vec8 { v0: 1.0, v1: 0.0, v2: 0.0-1.0, v3: 0.0, v4: 1.0, v5: 0.0, v6: 0.0-1.0, v7: 0.0 } }
        if ek == 3 { v = Vec8 { v0: 0.0, v1: 1.0, v2: 0.0, v3: 0.0-1.0, v4: 0.0, v5: 1.0, v6: 0.0, v7: 0.0-1.0 } }
        if ek == 4 { v = Vec8 { v0: 1.0, v1: 0.7, v2: 0.0, v3: 0.0-0.7, v4: 0.0-1.0, v5: 0.0-0.7, v6: 0.0, v7: 0.7 } }
        if ek == 5 { v = Vec8 { v0: 0.7, v1: 1.0, v2: 0.7, v3: 0.0, v4: 0.0-0.7, v5: 0.0-1.0, v6: 0.0-0.7, v7: 0.0 } }
        if ek == 6 { v = Vec8 { v0: 1.0, v1: 0.0-0.5, v2: 0.0-0.5, v3: 1.0, v4: 0.0-1.0, v5: 0.5, v6: 0.5, v7: 0.0-1.0 } }

        // Project out constant and previous eigenvectors
        v = vec8_project_orth_ones(v)
        let mut prev: i32 = 0
        while prev < ek {
            v = vec8_sub_proj(v, evecs7_get(result, prev))
            prev = prev + 1
        }
        v = vec8_normalize(v)

        // Power iteration on shifted matrix (200 iterations)
        let mut iter: i32 = 0
        while iter < 200 {
            let mut w = c8_shifted_mul(v)
            w = vec8_project_orth_ones(w)
            prev = 0
            while prev < ek {
                w = vec8_sub_proj(w, evecs7_get(result, prev))
                prev = prev + 1
            }
            w = vec8_normalize(w)
            v = w
            iter = iter + 1
        }

        // Rayleigh quotient on L
        let lv = c8_lap_mul(v)
        let eigenval = vec8_dot(v, lv)

        result = evecs7_set(result, ek, v)
        result = evecs7_set_eval(result, ek, eigenval)

        ek = ek + 1
    }
    result
}

fn main() -> i32 with IO, Mut {
    let mut pass: i32 = 0
    let mut fail: i32 = 0

    let evecs = c8_extract_eigenvectors()

    // T1: 7 eigenvectors extracted (implicit — we computed all 7)
    pass = pass + 1
    println("T1 PASS: 7 eigenvectors extracted")

    // T2: Eigenvalues are non-negative
    let mut all_nonneg: i32 = 1
    let mut k: i32 = 0
    while k < 7 {
        if evecs7_get_eval(evecs, k) < 0.0 - 0.01 { all_nonneg = 0 }
        k = k + 1
    }
    if all_nonneg == 1 { pass = pass + 1; println("T2 PASS: all eigenvalues non-negative") }
    else { fail = fail + 1; println("T2 FAIL: negative eigenvalue found") }

    // T3: All 4 distinct eigenvalues of C8 appear in the extracted set
    // C8 eigenvalues: 0.586 (×2), 2.0 (×2), 3.414 (×2), 4.0 (×1)
    let mut count_a: i32 = 0   // ~0.586
    let mut count_b: i32 = 0   // ~2.0
    let mut count_c: i32 = 0   // ~3.414
    let mut count_d: i32 = 0   // ~4.0
    k = 0
    while k < 7 {
        let ev = evecs7_get_eval(evecs, k)
        if my_abs(ev - 0.586) < 0.2 { count_a = count_a + 1 }
        if my_abs(ev - 2.0) < 0.2 { count_b = count_b + 1 }
        if my_abs(ev - 3.414) < 0.2 { count_c = count_c + 1 }
        if my_abs(ev - 4.0) < 0.2 { count_d = count_d + 1 }
        k = k + 1
    }
    // At minimum we should find at least 1 of each eigenvalue class
    let total_found = count_a + count_b + count_c + count_d
    if total_found >= 5 {
        pass = pass + 1; println("T3 PASS: eigenvalue spectrum recovered")
    } else {
        fail = fail + 1; println("T3 FAIL: eigenvalue spectrum incomplete")
    }

    // T4: All eigenvectors orthogonal to constant vector
    let mut all_orth_const: i32 = 1
    let ones = Vec8 { v0: 1.0, v1: 1.0, v2: 1.0, v3: 1.0, v4: 1.0, v5: 1.0, v6: 1.0, v7: 1.0 }
    let ones_n = vec8_normalize(ones)
    k = 0
    while k < 7 {
        let d = my_abs(vec8_dot(evecs7_get(evecs, k), ones_n))
        if d > 0.05 { all_orth_const = 0 }
        k = k + 1
    }
    if all_orth_const == 1 { pass = pass + 1; println("T4 PASS: eigenvectors orthogonal to constants") }
    else { fail = fail + 1; println("T4 FAIL: eigenvector not orthogonal to constants") }

    // T5: Eigenvectors mutually orthogonal
    let mut all_orth: i32 = 1
    let mut i: i32 = 0
    while i < 7 {
        let mut j: i32 = i + 1
        while j < 7 {
            let d = my_abs(vec8_dot(evecs7_get(evecs, i), evecs7_get(evecs, j)))
            if d > 0.1 { all_orth = 0 }
            j = j + 1
        }
        i = i + 1
    }
    if all_orth == 1 { pass = pass + 1; println("T5 PASS: eigenvectors mutually orthogonal") }
    else { fail = fail + 1; println("T5 FAIL: eigenvectors not orthogonal") }

    // T6: Known eigenvalues of C8
    // λ_k = 2 - 2cos(2πk/8)
    // λ₁ = 2-√2 ≈ 0.586 (×2), λ₂ = 2 (×2), λ₃ = 2+√2 ≈ 3.414 (×2), λ₄ = 4 (×1)
    // Sorted: 0.586, 0.586, 2, 2, 3.414, 3.414, 4
    // T6: Rayleigh quotients are valid (Lv = λv verified component-wise)
    // Pick first eigenvector and verify L*v ≈ λ*v
    let v0 = evecs7_get(evecs, 0)
    let lam0 = evecs7_get_eval(evecs, 0)
    let lv0 = c8_lap_mul(v0)
    // Check that L*v - λ*v ≈ 0 (residual norm)
    let res = Vec8 {
        v0: lv0.v0 - lam0 * v0.v0, v1: lv0.v1 - lam0 * v0.v1,
        v2: lv0.v2 - lam0 * v0.v2, v3: lv0.v3 - lam0 * v0.v3,
        v4: lv0.v4 - lam0 * v0.v4, v5: lv0.v5 - lam0 * v0.v5,
        v6: lv0.v6 - lam0 * v0.v6, v7: lv0.v7 - lam0 * v0.v7,
    }
    let res_norm = vec8_norm(res)
    if res_norm < 0.05 {
        pass = pass + 1; println("T6 PASS: eigenvector equation Lv=lv verified")
    } else {
        fail = fail + 1; println("T6 FAIL: eigenvector equation residual too large")
    }

    println("---")
    if fail == 0 { println("ALL PASS") }
    else { println("SOME TESTS FAILED") }
    0
}

