    var all_orth: i32 = 1
    var i: i32 = 0
    while i < 7 {
        var j: i32 = i + 1
        while j < 7 {
            let d = my_abs(vec8_dot(evecs7_get(evecs, i), evecs7_get(evecs, j)))
            if d > 0.1 { all_orth = 0 }
