// Test 5: Avalanche -- changing one bit in input changes at least 25% of output bits
fn test_avalanche() -> bool with IO, Mut, Panic, Div {
    let mut data1: [i64; 64] = [0; 64]
    data1[0] = 0
    let s1 = sha256_short(data1, 1)

    let mut data2: [i64; 64] = [0; 64]
    data2[0] = 1  // differ by one bit
    let s2 = sha256_short(data2, 1)

    // Count differing bits in XOR of hash words
    let mut diff_bits = 0
    let mut xor_val = s1.h0 ^ s2.h0
    let mut j = 0
    while j < 32 {
        if (xor_val & 1) != 0 { diff_bits = diff_bits + 1 }
        xor_val = xor_val >> 1
        j = j + 1
    }
    xor_val = s1.h1 ^ s2.h1
    j = 0
    while j < 32 {
        if (xor_val & 1) != 0 { diff_bits = diff_bits + 1 }
        xor_val = xor_val >> 1
        j = j + 1
    }
    xor_val = s1.h2 ^ s2.h2
    j = 0
    while j < 32 {
        if (xor_val & 1) != 0 { diff_bits = diff_bits + 1 }
        xor_val = xor_val >> 1
        j = j + 1
    }
    xor_val = s1.h3 ^ s2.h3
    j = 0
    while j < 32 {
        if (xor_val & 1) != 0 { diff_bits = diff_bits + 1 }
        xor_val = xor_val >> 1
        j = j + 1
    }
    xor_val = s1.h4 ^ s2.h4
    j = 0
    while j < 32 {
        if (xor_val & 1) != 0 { diff_bits = diff_bits + 1 }
        xor_val = xor_val >> 1
        j = j + 1
    }
    xor_val = s1.h5 ^ s2.h5
    j = 0
    while j < 32 {
        if (xor_val & 1) != 0 { diff_bits = diff_bits + 1 }
        xor_val = xor_val >> 1
        j = j + 1
    }
    xor_val = s1.h6 ^ s2.h6
    j = 0
    while j < 32 {
        if (xor_val & 1) != 0 { diff_bits = diff_bits + 1 }
        xor_val = xor_val >> 1
        j = j + 1
    }
    xor_val = s1.h7 ^ s2.h7
    j = 0
    while j < 32 {
        if (xor_val & 1) != 0 { diff_bits = diff_bits + 1 }
        xor_val = xor_val >> 1
        j = j + 1
    }

    // At least 64 of 256 bits should differ (25%)
    // In practice SHA-256 flips ~128 bits on average
    return diff_bits >= 64
}

// Test 6: Constant-time comparison works correctly
fn test_ct_equal() -> bool with IO, Mut, Panic, Div {
    let mut a: [i64; 64] = [0; 64]
    let mut b: [i64; 64] = [0; 64]
    let mut c: [i64; 64] = [0; 64]

    let mut i = 0
    while i < 32 {
        a[i] = (i * 17 + 3) as i64
        b[i] = (i * 17 + 3) as i64
        c[i] = (i * 17 + 4) as i64   // differ by 1 in every byte
        i = i + 1
    }

    let eq_ok = hash_equals_ct(a, b, 32)
    let neq_ok = hash_equals_ct(a, c, 32) == false

    return eq_ok && neq_ok
}

