// ============================================================================
// SHA-256 STATE
// ============================================================================

struct Sha256State {
    h0: i64,
    h1: i64,
    h2: i64,
    h3: i64,
    h4: i64,
    h5: i64,
    h6: i64,
    h7: i64,
}

fn sha256_init() -> Sha256State with Mut, Panic {
