    if v < 0.0 {
        print("-");
        let nv = 0.0 - v;
        let ip = nv as i64;
        let frac = ((nv - (ip as f64)) * 1000.0) as i64;
        print_int(ip);
        print(".");
        if frac < 100 { print("0") }
        if frac < 10 { print("0") }
        print_int(frac);
        return 0;
