    let ip = v as i64;
    let frac = ((v - (ip as f64)) * 1000.0) as i64;
    print_int(ip);
    print(".");
    if frac < 100 { print("0") }
    if frac < 10 { print("0") }
    print_int(frac);
    return 0;
}

fn print_f64_1(v: f64) -> i64 {
    if v < 0.0 {
