// === Eigenvector frame → Vec7 frame (project 8-dim eigenvectors to 7-dim) ===
// Each eigenvector ψ_k (8 components) maps to e_k in the octonion basis.
// The G₂ 3-form operates on the 7-frame of eigenvectors directly.
// Each "vector" in the frame is 8-dimensional (one component per brain region).
// But our G₂ infrastructure uses Vec7 (7-dim vectors in the frame).
//
// Actually: the frame has 7 vectors, each of dimension n (=8 here).
// The G₂ 3-form uses inner products between these vectors.
// So we need vec8 inner products, mapped to the Frame7/Vec7 infrastructure.
//
// Simplest: compute the 7×7 Gram matrix directly from Vec8 eigenvectors,
// then evaluate G₂ 3-form and SU(3) quality on the Gram matrix.

// === Cayley-Dickson sign ===

fn cd_sigma_r(a: i32, b: i32, bits: i32) -> i32 with Mut, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return 0 - 1 }
    let half = 1 << (bits - 1)
    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & (half - 1)
    let b_lo = b & (half - 1)
    if a_hi == 0 && b_hi == 0 { return cd_sigma_r(a_lo, b_lo, bits - 1) }
    if a_hi == 0 && b_hi == 1 { return cd_sigma_r(b_lo, a_lo, bits - 1) }
    if a_hi == 1 && b_hi == 0 {
        if b_lo == 0 { return cd_sigma_r(a_lo, b_lo, bits - 1) }
        return 0 - cd_sigma_r(a_lo, b_lo, bits - 1)
    }
    if b_lo == 0 { return 0 - cd_sigma_r(b_lo, a_lo, bits - 1) }
    cd_sigma_r(b_lo, a_lo, bits - 1)
}

fn cd_sigma(a: i32, b: i32) -> i32 with Mut, Div { cd_sigma_r(a, b, 3) }

// === Fano lines ===

fn fano_line_i(n: i32) -> i32 {
    if n == 0 { return 1 } if n == 1 { return 1 } if n == 2 { return 1 }
    if n == 3 { return 2 } if n == 4 { return 2 } if n == 5 { return 3 }
    3
}

fn fano_line_j(n: i32) -> i32 {
    if n == 0 { return 2 } if n == 1 { return 4 } if n == 2 { return 7 }
    if n == 3 { return 4 } if n == 4 { return 5 } if n == 5 { return 4 }
    6
}

fn fano_line_k(n: i32) -> i32 {
    if n == 0 { return 3 } if n == 1 { return 5 } if n == 2 { return 6 }
    if n == 3 { return 6 } if n == 4 { return 7 } if n == 5 { return 7 }
    5
}

// === G₂ 3-form on Gram matrix ===
// Given the 7×7 Gram matrix G[i][j] = ⟨ψ_i, ψ_j⟩, compute φ.
// G stored as Gram49 struct.

struct Gram49 {
    g00: f32, g01: f32, g02: f32, g03: f32, g04: f32, g05: f32, g06: f32,
    g10: f32, g11: f32, g12: f32, g13: f32, g14: f32, g15: f32, g16: f32,
    g20: f32, g21: f32, g22: f32, g23: f32, g24: f32, g25: f32, g26: f32,
    g30: f32, g31: f32, g32: f32, g33: f32, g34: f32, g35: f32, g36: f32,
    g40: f32, g41: f32, g42: f32, g43: f32, g44: f32, g45: f32, g46: f32,
    g50: f32, g51: f32, g52: f32, g53: f32, g54: f32, g55: f32, g56: f32,
    g60: f32, g61: f32, g62: f32, g63: f32, g64: f32, g65: f32, g66: f32,
}

fn gram_get(g: Gram49, i: i32, j: i32) -> f32 {
    let idx = i * 7 + j
    if idx == 0 { return g.g00 } if idx == 1 { return g.g01 } if idx == 2 { return g.g02 }
    if idx == 3 { return g.g03 } if idx == 4 { return g.g04 } if idx == 5 { return g.g05 }
    if idx == 6 { return g.g06 } if idx == 7 { return g.g10 } if idx == 8 { return g.g11 }
    if idx == 9 { return g.g12 } if idx == 10 { return g.g13 } if idx == 11 { return g.g14 }
    if idx == 12 { return g.g15 } if idx == 13 { return g.g16 } if idx == 14 { return g.g20 }
    if idx == 15 { return g.g21 } if idx == 16 { return g.g22 } if idx == 17 { return g.g23 }
    if idx == 18 { return g.g24 } if idx == 19 { return g.g25 } if idx == 20 { return g.g26 }
    if idx == 21 { return g.g30 } if idx == 22 { return g.g31 } if idx == 23 { return g.g32 }
    if idx == 24 { return g.g33 } if idx == 25 { return g.g34 } if idx == 26 { return g.g35 }
    if idx == 27 { return g.g36 } if idx == 28 { return g.g40 } if idx == 29 { return g.g41 }
    if idx == 30 { return g.g42 } if idx == 31 { return g.g43 } if idx == 32 { return g.g44 }
    if idx == 33 { return g.g45 } if idx == 34 { return g.g46 } if idx == 35 { return g.g50 }
    if idx == 36 { return g.g51 } if idx == 37 { return g.g52 } if idx == 38 { return g.g53 }
    if idx == 39 { return g.g54 } if idx == 40 { return g.g55 } if idx == 41 { return g.g56 }
    if idx == 42 { return g.g60 } if idx == 43 { return g.g61 } if idx == 44 { return g.g62 }
    if idx == 45 { return g.g63 } if idx == 46 { return g.g64 } if idx == 47 { return g.g65 }
    g.g66
}

// Build Gram matrix from eigenvectors
fn build_gram(evecs: Evecs7) -> Gram49 {
    Gram49 {
        g00: vec8_dot(evecs.e0, evecs.e0), g01: vec8_dot(evecs.e0, evecs.e1),
        g02: vec8_dot(evecs.e0, evecs.e2), g03: vec8_dot(evecs.e0, evecs.e3),
        g04: vec8_dot(evecs.e0, evecs.e4), g05: vec8_dot(evecs.e0, evecs.e5),
        g06: vec8_dot(evecs.e0, evecs.e6),
        g10: vec8_dot(evecs.e1, evecs.e0), g11: vec8_dot(evecs.e1, evecs.e1),
        g12: vec8_dot(evecs.e1, evecs.e2), g13: vec8_dot(evecs.e1, evecs.e3),
        g14: vec8_dot(evecs.e1, evecs.e4), g15: vec8_dot(evecs.e1, evecs.e5),
        g16: vec8_dot(evecs.e1, evecs.e6),
        g20: vec8_dot(evecs.e2, evecs.e0), g21: vec8_dot(evecs.e2, evecs.e1),
        g22: vec8_dot(evecs.e2, evecs.e2), g23: vec8_dot(evecs.e2, evecs.e3),
        g24: vec8_dot(evecs.e2, evecs.e4), g25: vec8_dot(evecs.e2, evecs.e5),
        g26: vec8_dot(evecs.e2, evecs.e6),
        g30: vec8_dot(evecs.e3, evecs.e0), g31: vec8_dot(evecs.e3, evecs.e1),
        g32: vec8_dot(evecs.e3, evecs.e2), g33: vec8_dot(evecs.e3, evecs.e3),
        g34: vec8_dot(evecs.e3, evecs.e4), g35: vec8_dot(evecs.e3, evecs.e5),
        g36: vec8_dot(evecs.e3, evecs.e6),
        g40: vec8_dot(evecs.e4, evecs.e0), g41: vec8_dot(evecs.e4, evecs.e1),
        g42: vec8_dot(evecs.e4, evecs.e2), g43: vec8_dot(evecs.e4, evecs.e3),
        g44: vec8_dot(evecs.e4, evecs.e4), g45: vec8_dot(evecs.e4, evecs.e5),
        g46: vec8_dot(evecs.e4, evecs.e6),
        g50: vec8_dot(evecs.e5, evecs.e0), g51: vec8_dot(evecs.e5, evecs.e1),
        g52: vec8_dot(evecs.e5, evecs.e2), g53: vec8_dot(evecs.e5, evecs.e3),
        g54: vec8_dot(evecs.e5, evecs.e4), g55: vec8_dot(evecs.e5, evecs.e5),
        g56: vec8_dot(evecs.e5, evecs.e6),
        g60: vec8_dot(evecs.e6, evecs.e0), g61: vec8_dot(evecs.e6, evecs.e1),
        g62: vec8_dot(evecs.e6, evecs.e2), g63: vec8_dot(evecs.e6, evecs.e3),
        g64: vec8_dot(evecs.e6, evecs.e4), g65: vec8_dot(evecs.e6, evecs.e5),
        g66: vec8_dot(evecs.e6, evecs.e6),
