    var passed: i64 = 0
    var failed: i64 = 0

    print("T1: GP fit succeeds (Cholesky valid).... ")
    if test_gp_fit(model) {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("T2: Interpolation at training points.... ")
    if test_interpolation(model, data) {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
