    // Row stride = 3 for K3 (n=3 used in glp_laplacian/glp_trace)
    // But glp_add_edge uses stride n=3
    glp_add_edge(&! adj, 3, 0, 1)
    glp_add_edge(&! adj, 3, 1, 2)
    glp_add_edge(&! adj, 3, 0, 2)
