                           0.0, 0.0, 0.0, 0.0]
    glp_laplacian(adj, 3, &! lap)
    let tr = glp_trace(lap, 3)
    return glp_abs(tr - 6.0) < 0.0001
}

// Test 3: Star S3 (center=0, leaves=1,2,3, 3 edges) — must be connected
fn test_star_s3_connected() -> bool with Div, Mut, Panic {
    var adj = glp_zero_adj()
    glp_add_edge(&! adj, 4, 0, 1)
    glp_add_edge(&! adj, 4, 0, 2)
    glp_add_edge(&! adj, 4, 0, 3)
    return glp_is_connected(adj, 4)
}

// Test 4: Empty graph on 4 nodes (no edges) — must NOT be connected
fn test_empty_disconnected() -> bool with Div, Mut, Panic {
    let adj = glp_zero_adj()
    return glp_is_connected(adj, 4) == false
}

