    println(u_c_analytical)
    println("  GUM u_c: 32.0")
    println("  Relative difference:")
    println(err_vs_gum)

    if err_vs_gum > 0.05 {
        println("FAIL: u_c deviates >5% from published GUM value")
        return 2
    }
    println("  [PASS] u_c within 5% of GUM published value")

