    // y = x^2 - x + 1: y(0)=1, y(1)=1, y(2)=3, y(3)=7
    xs[0] = 0.0; ys[0] = 1.0
    xs[1] = 1.0; ys[1] = 1.0
    xs[2] = 2.0; ys[2] = 3.0
    xs[3] = 3.0; ys[3] = 7.0

