        buffer[24 + i] = i + 10;
        i = i + 1;
    }
    var sum: i64 = 0;
    i = 0;
    while i < 8 {
        sum = sum + buffer[24 + i];
        i = i + 1;
    }
    if sum == 108 { n_pass = n_pass + 1 }

    if n_pass == 4 { return 0 } else { return 1 }
}

