// T3: det(I_n) = 1
fn test_det_identity() -> i64 with Mut, Div, Panic {
    let eye3 = matnm_identity(3)
    let d3 = matnm_det(eye3)

    let eye4 = matnm_identity(4)
    let d4 = matnm_det(eye4)

    if matnm_abs(d3 - 1.0) < 1e-10 {
        if matnm_abs(d4 - 1.0) < 1e-10 {
            return 1
        }
    }
