    // ========================================================================
    {
        let mut data: NLMEData = NLMEData {
            times: [0.0; 2048],
            observations: [0.0; 2048],
            n_obs: [0; 32],
            doses: [0.0; 32],
            n_individuals: 1
        }

        let true_ka = 4.4 * t_exp(0.2)
        let true_cl = 5.46 * t_exp(-0.15)
