    print("Test 4: Conjugate Operation")
    print("Conjugate negates all imaginary components")

    // Verify property: norm(o) = norm(conj(o))
    let norm_o = oct_norm(o)
    let norm_conj = oct_norm(o_conj)

    if norm_o > norm_conj - 0.01 && norm_o < norm_conj + 0.01 {
        print("✓ conjugate preserves norm")
