    println("<head>");
    println("<meta charset=\"UTF-8\">");
    print("<title>");
    print(config.title);
    println("</title>");
    println("<style>");
    print("  body { background: ");
    print(config.bg_color);
    println("; color: #e0e0e0; font-family: sans-serif; }");
    println("  canvas { border: 1px solid #333; cursor: grab; }");
    println("</style>");
    println("</head>");
    println("<body>");
    print("<h1>");
    print(config.title);
    println("</h1>");
    print("<canvas id=\"c\" width=\"");
    p3d_print_int(config.width);
    print("\" height=\"");
