// ============================================================================
// TYPES (inlined from stdlib/plot/plot3d.sio)
// ============================================================================

struct Plot3DConfig {
    width: i64,
    height: i64,
    title: string,
    x_label: string,
    y_label: string,
    z_label: string,
    camera_angle_x: f64,
    camera_angle_y: f64,
    bg_color: string,
}

struct Scatter3D {
    x: [f64; 512],
    y: [f64; 512],
    z: [f64; 512],
    n: i64,
    color: string,
    point_size: f64,
}

struct Surface3D {
    z_grid: [f64; 4096],
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
    nx: i64,
    ny: i64,
}

// ============================================================================
// CONSTRUCTORS
// ============================================================================

fn plot3d_config_default() -> Plot3DConfig {
    Plot3DConfig {
        width: 800,
        height: 600,
        title: "3D Plot",
        x_label: "X",
        y_label: "Y",
        z_label: "Z",
        camera_angle_x: 0.6,
        camera_angle_y: 0.8,
        bg_color: "#1a1a2e",
    }
}

fn scatter3d_new() -> Scatter3D {
    Scatter3D {
        x: [0.0; 512],
        y: [0.0; 512],
        z: [0.0; 512],
        n: 0,
        color: "#00d4ff",
        point_size: 4.0,
    }
}

fn scatter3d_add_point(s: &!Scatter3D, xv: f64, yv: f64, zv: f64) {
    if s.n < 512 {
        s.x[s.n as usize] = xv
        s.y[s.n as usize] = yv
        s.z[s.n as usize] = zv
        s.n = s.n + 1
    }
}

fn surface3d_new() -> Surface3D {
    Surface3D {
        z_grid: [0.0; 4096],
        x_min: -1.0,
        x_max: 1.0,
        y_min: -1.0,
        y_max: 1.0,
        nx: 8,
        ny: 8,
    }
}

fn surface3d_set(s: &!Surface3D, ix: i64, iy: i64, z_val: f64) {
    if ix >= 0 && ix < s.nx && iy >= 0 && iy < s.ny {
        let idx = iy * s.nx + ix
        if idx < 4096 {
            s.z_grid[idx as usize] = z_val
        }
    }
}

