// ============================================================================
// TEST DATA GENERATION
// ============================================================================
// Simple deterministic data: cell(r, c) = (r + 1) * 10 + (c + 1)
// e.g., for 3x2: [[11, 12], [21, 22], [31, 32]]

fn make_test_matrix(rows: i64, cols: i64) -> MatrixData with Mut, Panic {
    var m = matrix_data_new(rows, cols)
    var r: i64 = 0
    while r < rows {
        var c: i64 = 0
        while c < cols {
            let val = ((r + 1) * 10 + (c + 1)) as f64
            m = matrix_data_set(m, r, c, val)
            c = c + 1
        }
        r = r + 1
    }
    m
}

// ============================================================================
// T1: CSV FORMAT TEST
// ============================================================================
// Verifies:
//   - Header row has correct number of comma-separated column names
//   - Data values match expected pattern
//   - Row count matches (1 header + rows data lines)

fn test_csv_format() -> bool with IO, Mut, Panic, Div {
    println("--- T1: CSV format test ---")
    let rows: i64 = 3
    let cols: i64 = 2
    let m = make_test_matrix(rows, cols)

    // Print CSV (will appear in output)
    print_csv(m.data, rows, cols)

    // Verify data values match expected pattern
    let v00 = m.data[0]  // row 0, col 0 = 11.0
    let v01 = m.data[1]  // row 0, col 1 = 12.0
    let v10 = m.data[2]  // row 1, col 0 = 21.0
    let v11 = m.data[3]  // row 1, col 1 = 22.0
    let v20 = m.data[4]  // row 2, col 0 = 31.0
    let v21 = m.data[5]  // row 2, col 1 = 32.0

    let ok1 = v00 > 10.9 && v00 < 11.1
    let ok2 = v01 > 11.9 && v01 < 12.1
    let ok3 = v10 > 20.9 && v10 < 21.1
    let ok4 = v11 > 21.9 && v11 < 22.1
    let ok5 = v20 > 30.9 && v20 < 31.1
    let ok6 = v21 > 31.9 && v21 < 32.1

    ok1 && ok2 && ok3 && ok4 && ok5 && ok6
}

// ============================================================================
// T2: JSON MATRIX FORMAT TEST
// ============================================================================
// Verifies:
