    println("--- T3: Epistemic CSV test ---")
    let rows: i64 = 2
    let cols: i64 = 2

    // Values: deterministic pattern (use globals to avoid large stack locals)
    G_SCI_VALUES[0] = 1.5
    G_SCI_VALUES[1] = 2.3
    G_SCI_VALUES[2] = 3.7
    G_SCI_VALUES[3] = 4.1
    G_SCI_UNCERTS[0] = 0.15
    G_SCI_UNCERTS[1] = 0.23
    G_SCI_UNCERTS[2] = 0.37
    G_SCI_UNCERTS[3] = 0.41

