    let ok1 = G_SCI_VALUES[0] > 1.49 && G_SCI_VALUES[0] < 1.51
    let ok2 = G_SCI_UNCERTS[0] > 0.14 && G_SCI_UNCERTS[0] < 0.16
    let ok3 = G_SCI_VALUES[3] > 4.09 && G_SCI_VALUES[3] < 4.11
    let ok4 = G_SCI_UNCERTS[3] > 0.40 && G_SCI_UNCERTS[3] < 0.42

