fn test_csv_roundtrip_dims() -> i64 with IO, Mut, Panic, Div {
    println("--- T4: CSV round-trip dimensions test ---")
    var ok: i64 = 1

    // Build 4x5 matrix in global array: cell(r,c) = (r+1)*10 + (c+1)
    // Avoids passing [f64; 4096] to any function (lean_single call-site table limit)
    let rows: i64 = 4
    let cols: i64 = 5
    let total = rows * cols
    if total != 20 { ok = 0 }

    var r: i64 = 0
    while r < rows {
        var c: i64 = 0
        while c < cols {
            G_SCI_VALUES[(r * cols + c) as usize] = ((r + 1) * 10 + (c + 1)) as f64
            c = c + 1
        }
        r = r + 1
    }

    // Verify values directly from global array (no function calls passing [f64;4096])
    // m[0,0]=11, m[0,4]=15, m[3,0]=41, m[3,4]=45 (row-major, 5 cols)
    if G_SCI_VALUES[0] < 10.9 { ok = 0 }
    if G_SCI_VALUES[0] > 11.1 { ok = 0 }
    if G_SCI_VALUES[4] < 14.9 { ok = 0 }
    if G_SCI_VALUES[4] > 15.1 { ok = 0 }
    if G_SCI_VALUES[15] < 40.9 { ok = 0 }
    if G_SCI_VALUES[15] > 41.1 { ok = 0 }
    if G_SCI_VALUES[19] < 44.9 { ok = 0 }
    if G_SCI_VALUES[19] > 45.1 { ok = 0 }

    // Print the NPY header (only passes scalar args — safe)
    print_npy_header(rows, cols)

    ok
}

