        let r_val: i64 = 2836
        let hi = rng / q
        let lo = rng - hi * q
        let t = a * lo - r_val * hi
        if t > 0 {
            rng = t
        } else {
            rng = t + m
        }
        var j_val = rng
        if j_val < 0 {
            j_val = 0 - j_val
        }
        j_val = j_val - (j_val / ((i as i64) + 1)) * ((i as i64) + 1)
        let j_i32 = j_val as i32
        let tmp = p.data[i]
        p.data[i] = p.data[j_i32]
        p.data[j_i32] = tmp
        i = i - 1
    }
    rng
}

// ============================================================================
// LINEAR ALGEBRA (fixed-size arrays)
// ============================================================================

fn slop_dot(a: &[f64; 64], b: &[f64; 64], n: i32) -> f64 with Mut, Panic {
    var sum: f64 = 0.0
    var i: i32 = 0
    while i < n {
        sum = sum + a[i] * b[i]
        i = i + 1
    }
    sum
}

fn slop_norm(a: &[f64; 64], n: i32) -> f64 with Mut, Div, Panic {
    var sum: f64 = 0.0
    var i: i32 = 0
    while i < n {
        sum = sum + a[i] * a[i]
        i = i + 1
    }
    t_sqrt(sum)
}

fn slop_scale(a: &[f64; 64], alpha: f64, out: &![f64; 64], n: i32) with Mut, Panic {
    var i: i32 = 0
    while i < n {
        out[i] = alpha * a[i]
        i = i + 1
    }
}

fn slop_axpy(alpha: f64, a: &[f64; 64], b: &[f64; 64], out: &![f64; 64], n: i32) with Mut, Panic {
    var i: i32 = 0
    while i < n {
        out[i] = alpha * a[i] + b[i]
        i = i + 1
    }
}

fn slop_matvec(a: &[f64; 4096], x: &[f64; 64], out: &![f64; 64],
               m_dim: i32, n: i32) with Mut, Panic {
    var i: i32 = 0
    while i < m_dim {
        var sum: f64 = 0.0
        var j: i32 = 0
        while j < n {
            sum = sum + a[i * n + j] * x[j]
            j = j + 1
        }
        out[i] = sum
        i = i + 1
    }
}

fn slop_matmul(a: &[f64; 4096], b: &[f64; 4096], c: &![f64; 4096],
               m_dim: i32, k_dim: i32, n: i32) with Mut, Panic {
    var i: i32 = 0
    while i < m_dim {
        var j: i32 = 0
        while j < n {
            var sum: f64 = 0.0
            var p: i32 = 0
            while p < k_dim {
                sum = sum + a[i * k_dim + p] * b[p * n + j]
                p = p + 1
            }
            c[i * n + j] = sum
            j = j + 1
        }
        i = i + 1
    }
}

fn slop_transpose(a: &[f64; 4096], b: &![f64; 4096], m_dim: i32, n: i32) with Mut, Panic {
    var i: i32 = 0
    while i < m_dim {
        var j: i32 = 0
        while j < n {
            b[j * m_dim + i] = a[i * n + j]
            j = j + 1
        }
        i = i + 1
    }
}

