fn t_abs(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    t_abs(a - b) < tol
}

fn t_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    let mut y = x
    if y < 1.0 { y = 1.0 }
    let mut i: i32 = 0
    while i < 60 {
        y = 0.5 * (y + x / y)
        i = i + 1
