// ============================================================================
// PERMUTATION (struct wrapper for i64 array)
// ============================================================================

struct Perm128 {
    data: [i64; 128]
}

fn next_permutation(p: &!Perm128, n: i32) -> bool with Mut, Panic {
    let mut i = n - 2
    while i >= 0 {
        if p.data[i] < p.data[i + 1] {
            let mut j = n - 1
            while p.data[j] <= p.data[i] {
                j = j - 1
            }
            let tmp = p.data[i]
            p.data[i] = p.data[j]
            p.data[j] = tmp
            let mut lo = i + 1
            let mut hi = n - 1
            while lo < hi {
                let t = p.data[lo]
                p.data[lo] = p.data[hi]
                p.data[hi] = t
                lo = lo + 1
                hi = hi - 1
            }
            return true
        }
        i = i - 1
    }
    return false
}

fn count_permutations(n: i32) -> i32 with Mut, Panic {
    let mut p = Perm128 { data: [0; 128] }
    let mut i: i32 = 0
    while i < n {
        p.data[i] = i as i64
        i = i + 1
    }
    let mut count: i32 = 1
    while next_permutation(&!p, n) {
        count = count + 1
    }
    count
}

fn shuffle_perm(p: &!Perm128, n: i32, seed: i64) -> i64 with Mut, Div, Panic {
