}

fn sqrt_f64(x: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 }
    var scaled = x;
    var scale_back = 1.0;
    while scaled < 1.0 {
        scaled = scaled * 4.0;
        scale_back = scale_back * 2.0;
    }
    while scaled > 4.0 {
        scaled = scaled * 0.25;
        scale_back = scale_back * 0.5;
    }
    var y = 1.5;
    y = 0.5 * (y + scaled / y);
