fn sparse_matvec(a: SparseCSR, x: [f64; 128], n: i32) -> [f64; 128] with Mut, Panic, Div {
    var y: [f64; 128] = [0.0; 128];
    var i = 0;
    while i < a.nrows {
        var sum = 0.0;
        var k = a.row_ptr[i];
        let row_end = a.row_ptr[i + 1];
        while k < row_end {
            let col = a.col_idx[k];
            sum = sum + a.values[k] * x[col];
            k = k + 1;
        }
        y[i] = sum;
        i = i + 1;
    }
    return y;
}

fn sparse_matvec_add(
    a: SparseCSR,
    x: [f64; 128],
    y: [f64; 128],
    alpha: f64,
    beta: f64,
    n: i32;
) -> [f64; 128] with Mut, Panic, Div {
    var result: [f64; 128] = [0.0; 128];
    var i = 0;
    while i < a.nrows {
        var sum = 0.0;
        var k = a.row_ptr[i];
        let row_end = a.row_ptr[i + 1];
        while k < row_end {
            let col = a.col_idx[k];
            sum = sum + a.values[k] * x[col];
            k = k + 1;
        }
        result[i] = alpha * sum + beta * y[i];
        i = i + 1;
    }
    return result;
}

// ============================================================================
// SPARSE-SPARSE OPERATIONS
// ============================================================================

fn sparse_add(a: SparseCSR, b: SparseCSR) -> SparseCSR with Mut, Panic, Div {
    var result = SparseCSR {
        values: [0.0; 1024],
        col_idx: [0; 1024],
        row_ptr: [0; 129],
        nrows: a.nrows,
        ncols: a.ncols,
        nnz: 0;
    }

    var pos = 0;
    var i = 0;
    while i < a.nrows {
        result.row_ptr[i] = pos;

        var ka = a.row_ptr[i];
        let ka_end = a.row_ptr[i + 1];
        var kb = b.row_ptr[i];
        let kb_end = b.row_ptr[i + 1];

        while ka < ka_end && kb < kb_end {
            if a.col_idx[ka] < b.col_idx[kb] {
                result.values[pos] = a.values[ka];
                result.col_idx[pos] = a.col_idx[ka];
                pos = pos + 1;
                ka = ka + 1;
            } else if a.col_idx[ka] > b.col_idx[kb] {
                result.values[pos] = b.values[kb];
                result.col_idx[pos] = b.col_idx[kb];
                pos = pos + 1;
                kb = kb + 1;
            } else {
                let sum = a.values[ka] + b.values[kb];
                if abs_f64(sum) > 1e-30 {
                    result.values[pos] = sum;
                    result.col_idx[pos] = a.col_idx[ka];
                    pos = pos + 1;
                }
                ka = ka + 1;
                kb = kb + 1;
            }
        }
        while ka < ka_end {
            result.values[pos] = a.values[ka];
            result.col_idx[pos] = a.col_idx[ka];
            pos = pos + 1;
            ka = ka + 1;
        }
        while kb < kb_end {
            result.values[pos] = b.values[kb];
            result.col_idx[pos] = b.col_idx[kb];
            pos = pos + 1;
            kb = kb + 1;
        }

        i = i + 1;
    }
    result.row_ptr[a.nrows] = pos;
    result.nnz = pos;
    return result;
}

fn sparse_scale(a: SparseCSR, alpha: f64) -> SparseCSR with Mut, Panic, Div {
    var result = a;
    var i = 0;
    while i < a.nnz {
        result.values[i] = alpha * a.values[i];
        i = i + 1;
    }
    return result;
}

fn sparse_transpose(a: SparseCSR) -> SparseCSR with Mut, Panic, Div {
    var result = SparseCSR {
        values: [0.0; 1024],
        col_idx: [0; 1024],
        row_ptr: [0; 129],
        nrows: a.ncols,
        ncols: a.nrows,
        nnz: a.nnz;
    }

    var col_count: [i32; 129] = [0; 129];
    var k = 0;
    while k < a.nnz {
        col_count[a.col_idx[k]] = col_count[a.col_idx[k]] + 1;
        k = k + 1;
    }

    result.row_ptr[0] = 0;
    var i = 0;
    while i < a.ncols {
        result.row_ptr[i + 1] = result.row_ptr[i] + col_count[i];
        i = i + 1;
    }

    var pos: [i32; 129] = [0; 129];
    i = 0;
    while i < a.ncols {
        pos[i] = result.row_ptr[i];
        i = i + 1;
    }

    i = 0;
    while i < a.nrows {
        k = a.row_ptr[i];
        let row_end = a.row_ptr[i + 1];
        while k < row_end {
            let col = a.col_idx[k];
            let dest = pos[col];
            result.values[dest] = a.values[k];
            result.col_idx[dest] = i;
            pos[col] = pos[col] + 1;
            k = k + 1;
        }
        i = i + 1;
    }

    return result;
}

// ============================================================================
// TRIANGULAR SOLVES
// ============================================================================

fn sparse_lower_solve(l: SparseCSR, b: [f64; 128], n: i32) -> [f64; 128] with Mut, Panic, Div {
    var x: [f64; 128] = [0.0; 128];
    var i = 0;
    while i < n {
        x[i] = b[i];
        var k = l.row_ptr[i];
        let row_end = l.row_ptr[i + 1];
        var diag_val = 1.0;

        while k < row_end {
            let col = l.col_idx[k];
            if col < i {
                x[i] = x[i] - l.values[k] * x[col];
            } else if col == i {
                diag_val = l.values[k];
            }
            k = k + 1;
        }
        x[i] = x[i] / diag_val;
        i = i + 1;
    }
    return x;
}

fn sparse_upper_solve(u: SparseCSR, b: [f64; 128], n: i32) -> [f64; 128] with Mut, Panic, Div {
    var x: [f64; 128] = [0.0; 128];
    var i = 0;
    while i < n {
        x[i] = b[i];
        i = i + 1;
    }

    i = n - 1;
    while i >= 0 {
        var k = u.row_ptr[i];
        let row_end = u.row_ptr[i + 1];
        var diag_val = 1.0;

        while k < row_end {
            let col = u.col_idx[k];
            if col > i {
                x[i] = x[i] - u.values[k] * x[col];
            } else if col == i {
                diag_val = u.values[k];
            }
            k = k + 1;
        }
        x[i] = x[i] / diag_val;
        i = i - 1;
    }
    return x;
}

// ============================================================================
// MATRIX PROPERTIES
// ============================================================================

fn sparse_frobenius_norm(a: SparseCSR) -> f64 with Mut, Panic, Div {
    var sum = 0.0;
    var i = 0;
    while i < a.nnz {
        sum = sum + a.values[i] * a.values[i];
        i = i + 1;
    }
    return sqrt_f64(sum);
}

fn sparse_is_symmetric(a: SparseCSR, tol: f64) -> bool with Mut, Panic, Div {
    if a.nrows != a.ncols {
        return false;
    }
    var i = 0;
    while i < a.nrows {
        var k = a.row_ptr[i];
        let row_end = a.row_ptr[i + 1];
        while k < row_end {
            let j = a.col_idx[k];
            let aij = a.values[k];
            let aji = sparse_get(a, j, i);
            if abs_f64(aij - aji) > tol {
                return false;
            }
            k = k + 1;
        }
        i = i + 1;
    }
    return true;
}

// ============================================================================
// CONJUGATE GRADIENT SOLVER
// ============================================================================

fn cg_solve(
    a: SparseCSR,
    b: [f64; 128],
    x0: [f64; 128],
    n: i32,
    tol: f64,
    max_iter: i32;
) -> CGResult with Mut, Panic, Div {
    var x: [f64; 128] = [0.0; 128];
    var i = 0;
    while i < n {
        x[i] = x0[i];
        i = i + 1;
    }

    let ax = sparse_matvec(a, x, n);
    var r = vec_sub(b, ax, n);
    var p = vec_copy(r, n);
    var rsold = vec_dot(r, r, n);

    if sqrt_f64(rsold) < tol {
        return CGResult {
            x: x,
            iterations: 0,
            residual: sqrt_f64(rsold),
            converged: true;
        }
    }

    var iter = 0;
    var converged = false;
    var done = false;
    while iter < max_iter && !done {
        let ap = sparse_matvec(a, p, n);
        let pap = vec_dot(p, ap, n);
        if abs_f64(pap) < 1e-30 {
            // Breakdown;
            done = true;
        } else {
            let alpha = rsold / pap;

            i = 0;
            while i < n {
                x[i] = x[i] + alpha * p[i];
                i = i + 1;
            }

            i = 0;
            while i < n {
                r[i] = r[i] - alpha * ap[i];
                i = i + 1;
            }

            let rsnew = vec_dot(r, r, n);

            if sqrt_f64(rsnew) < tol {
                converged = true;
                done = true;
            } else {
                let beta = rsnew / rsold;
                i = 0;
                while i < n {
                    p[i] = r[i] + beta * p[i];
                    i = i + 1;
                }

                rsold = rsnew;
            }
        }
        iter = iter + 1;
    }

    let final_res = sqrt_f64(vec_dot(r, r, n));

    return CGResult {
        x: x,
        iterations: iter,
        residual: final_res,
        converged: converged;
    }
}

