// Test 1: Identity matrix * x = x
fn test_identity_matvec() -> bool with IO, Mut, Panic, Div {
    let eye = sparse_identity(5)

    var x: [f64; 128] = [0.0; 128]
    x[0] = 1.0
    x[1] = 2.0
    x[2] = 3.0
