// Test 1: Identity matrix * x = x
fn test_identity_matvec() -> bool with IO, Mut, Panic, Div {
    let eye = sparse_identity(5)

    var x: [f64; 128] = [0.0; 128]
    x[0] = 1.0
    x[1] = 2.0
    x[2] = 3.0
    x[3] = 4.0
    x[4] = 5.0

    let y = sparse_matvec(eye, x, 5)

    var err = 0.0
    var i = 0
    while i < 5 {
        err = err + abs_f64(y[i] - x[i])
        i = i + 1
    }
    print("  err=")
    println!(err)
    return err < 1e-12
}

