fn test_cg_identity() -> bool with IO, Mut, Panic, Div {
    let n = 5
    let eye = sparse_identity(n)

    var b: [f64; 128] = [0.0; 128]
    b[0] = 1.0
    b[1] = 2.0
    b[2] = 3.0
    b[3] = 4.0
    b[4] = 5.0

    var x0: [f64; 128] = [0.0; 128]

    let result = cg_solve(eye, b, x0, n, 1e-10, 100)

    var err = 0.0
    var i = 0
    while i < n {
        let diff = abs_f64(result.x[i] - b[i])
