// Test 1: Gamma at positive integers -- Gamma(n) = (n-1)!
fn test_gamma_integers() -> bool with IO, Mut, Panic, Div {
    let g1 = sp_gamma(1.0)
    let g2 = sp_gamma(2.0)
    let g3 = sp_gamma(3.0)
    let g4 = sp_gamma(4.0)
    let g5 = sp_gamma(5.0)
    let g6 = sp_gamma(6.0)

    print("  G(1)=")
    println!(g1)
    print("  G(2)=")
    println!(g2)
