    println!(g3)
    print("  G(4)=")
    println!(g4)
    print("  G(5)=")
    println!(g5)
    print("  G(6)=")
    println!(g6)

    let tol = 1.0e-6
    let ok1 = abs_f64(g1 - 1.0) < tol
