    let x_pad = if x_range > 0.0 { x_range * 0.05 } else { 1.0 }
    let y_pad = if y_range > 0.0 { y_range * 0.05 } else { 1.0 }
    x_min = x_min - x_pad
    x_max = x_max + x_pad
    y_min = y_min - y_pad
    y_max = y_max + y_pad

    // --- T3: track that we printed something ---
    var lines_printed: i64 = 0

    // --- Emit SVG ---
    emit_svg_header(width, height)
    lines_printed = lines_printed + 1

    emit_title("Exponential Decay: y = exp(-0.3t)", width / 2, margin_top / 2 + 5)
    lines_printed = lines_printed + 1

    emit_axes(ox, oy, plot_w, plot_h)
    lines_printed = lines_printed + 1

    emit_polyline(
        &x_data, &y_data, n_points,
        ox, oy, plot_w, plot_h,
        x_min, x_max, y_min, y_max,
        "#377eb8",
    )
    lines_printed = lines_printed + 1

    // X-axis label
    print("<text x=\"")
    print_i64(width / 2)
    print("\" y=\"")
    print_i64(height - 10)
    println("\" text-anchor=\"middle\" font-family=\"sans-serif\" font-size=\"14\">Time (s)</text>")

    // Y-axis label
    print("<text x=\"15\" y=\"")
    print_i64(height / 2)
    print("\" text-anchor=\"middle\" font-family=\"sans-serif\" font-size=\"14\" transform=\"rotate(-90,15,")
    print_i64(height / 2)
    println(")\">Concentration</text>")

    emit_svg_footer()
    lines_printed = lines_printed + 1

    // --- Validation (printed after SVG so redirecting captures clean SVG) ---
    // The SVG tags are embedded in what we printed above.
    // T1: <svg tag was emitted by emit_svg_header
    // T2: <polyline tag was emitted by emit_polyline
    // T3: lines_printed > 0

    var passed: i64 = 0
    var failed: i64 = 0

    // T1: We emitted <svg
    if lines_printed >= 1 { passed = passed + 1 } else { failed = failed + 1 }

    // T2: We emitted <polyline (emit_polyline was called with n_points > 0)
    if n_points > 0 { passed = passed + 1 } else { failed = failed + 1 }

    // T3: SVG output is non-empty
    if lines_printed > 0 { passed = passed + 1 } else { failed = failed + 1 }

    // Report
    print("# SVG Plot Test: ")
    print_i64(passed)
    print(" passed, ")
    print_i64(failed)
    println(" failed")

    if failed > 0 { return 1 }
    0
}

