fn christoffel_from_metric(metric_fn: fn(&[f64; 4], i32, &mut [f64; 16]) with Mut, Div, Panic,
                           x: &[f64; 4], dim: i32,
                           gamma: &mut Christoffel4) with Mut, Div, Panic {
    let h = 1.0e-6
    gamma.c4_dim = dim

    var idx = 0
    while idx < 64 { gamma.gamma[idx] = 0.0; idx = idx + 1 }

    var g0: [f64; 16] = [0.0; 16]
    metric_fn(x, dim, &mut g0)

    var g_inv: [f64; 16] = [0.0; 16]
    metric_inverse(&g0, dim, &mut g_inv)

    var dg: [f64; 256] = [0.0; 256]

    var m = 0
    while m < dim {
        var xp: [f64; 4] = [0.0; 4]
        var xm: [f64; 4] = [0.0; 4]
        var c = 0
        while c < 4 { xp[c] = x[c]; xm[c] = x[c]; c = c + 1 }
        xp[m] = x[m] + h
        xm[m] = x[m] - h

        var gp: [f64; 16] = [0.0; 16]
        var gm: [f64; 16] = [0.0; 16]
        metric_fn(&xp, dim, &mut gp)
        metric_fn(&xm, dim, &mut gm)

        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                dg[m * dim * dim + i * dim + j] = (gp[i * dim + j] - gm[i * dim + j]) / (2.0 * h)
                j = j + 1
            }
            i = i + 1
        }
        m = m + 1
    }

    var k = 0
    while k < dim {
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                var s = 0.0
                var l = 0
                while l < dim {
                    let term1 = dg[j * dim * dim + l * dim + i]
                    let term2 = dg[i * dim * dim + l * dim + j]
                    let term3 = dg[l * dim * dim + i * dim + j]
                    s = s + g_inv[k * dim + l] * (term1 + term2 - term3)
                    l = l + 1
                }
                gamma.gamma[k * dim * dim + i * dim + j] = 0.5 * s
                j = j + 1
            }
            i = i + 1
        }
        k = k + 1
    }
}

