fn ricci_tensor(R_in: &RiemannTensor, result: &mut RicciTensor) with Mut, Div, Panic {
    let dim = R_in.rt_dim
    result.ric_dim = dim
    result.scalar = 0.0

    var i = 0
    while i < 16 { result.Ric[i] = 0.0; i = i + 1 }

    i = 0
    while i < dim {
        var j = 0
        while j < dim {
            var s = 0.0
            var k = 0
            while k < dim {
                s = s + R_in.R[k * dim * dim * dim + i * dim * dim + k * dim + j]
                k = k + 1
            }
            result.Ric[i * dim + j] = s
            j = j + 1
        }
        i = i + 1
    }
}

fn ricci_with_scalar(metric_fn: fn(&[f64; 4], i32, &mut [f64; 16]) with Mut, Div, Panic,
                     x: &[f64; 4], dim: i32,
                     result: &mut RicciTensor) with Mut, Div, Panic {
    var Riem: RiemannTensor = RiemannTensor { R: [0.0; 256], rt_dim: dim }
    riemann_tensor(metric_fn, x, dim, &mut Riem)

    ricci_tensor(&Riem, result)

    var g0: [f64; 16] = [0.0; 16]
    metric_fn(x, dim, &mut g0)
    var g_inv: [f64; 16] = [0.0; 16]
    metric_inverse(&g0, dim, &mut g_inv)

    var scalar = 0.0
    var i = 0
    while i < dim {
        var j = 0
        while j < dim {
            scalar = scalar + g_inv[i * dim + j] * result.Ric[i * dim + j]
            j = j + 1
        }
        i = i + 1
    }
    result.scalar = scalar
}

fn gauss_curvature_2d(metric_fn: fn(&[f64; 4], i32, &mut [f64; 16]) with Mut, Div, Panic,
                      x: &[f64; 4]) -> f64 with Mut, Div, Panic {
    let dim = 2
    var ric: RicciTensor = RicciTensor { Ric: [0.0; 16], scalar: 0.0, ric_dim: dim }
    ricci_with_scalar(metric_fn, x, dim, &mut ric)
    ric.scalar / 2.0
}

