fn geodesic_rhs(metric_fn: fn(&[f64; 4], i32, &mut [f64; 16]) with Mut, Div, Panic,
                st: &GeodesicState,
                dx: &mut [f64; 4], dv: &mut [f64; 4]) with Mut, Div, Panic {
    let dim = st.gs_dim

    var i = 0
    while i < 4 { dx[i] = 0.0; dv[i] = 0.0; i = i + 1 }
    i = 0
    while i < dim { dx[i] = st.v[i]; i = i + 1 }

    var gamma: Christoffel4 = Christoffel4 { gamma: [0.0; 64], c4_dim: dim }
    christoffel_from_metric(metric_fn, &st.x, dim, &mut gamma)

    var k = 0
    while k < dim {
        var s = 0.0
        i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * st.v[i] * st.v[j]
                j = j + 1
            }
            i = i + 1
        }
        dv[k] = 0.0 - s
        k = k + 1
    }
}

fn geodesic_step(metric_fn: fn(&[f64; 4], i32, &mut [f64; 16]) with Mut, Div, Panic,
                 st: &mut GeodesicState, dtau: f64) with Mut, Div, Panic {
    let dim = st.gs_dim

    var dx1: [f64; 4] = [0.0; 4]
    var dv1: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, st, &mut dx1, &mut dv1)

    var s2: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], gs_dim: dim, tau: st.tau + dtau / 2.0 }
    var c = 0
    while c < dim {
        s2.x[c] = st.x[c] + 0.5 * dtau * dx1[c]
        s2.v[c] = st.v[c] + 0.5 * dtau * dv1[c]
        c = c + 1
    }

    var dx2: [f64; 4] = [0.0; 4]
    var dv2: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, &s2, &mut dx2, &mut dv2)

    var s3: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], gs_dim: dim, tau: st.tau + dtau / 2.0 }
    c = 0
    while c < dim {
        s3.x[c] = st.x[c] + 0.5 * dtau * dx2[c]
        s3.v[c] = st.v[c] + 0.5 * dtau * dv2[c]
        c = c + 1
    }

    var dx3: [f64; 4] = [0.0; 4]
    var dv3: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, &s3, &mut dx3, &mut dv3)

    var s4: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], gs_dim: dim, tau: st.tau + dtau }
    c = 0
    while c < dim {
        s4.x[c] = st.x[c] + dtau * dx3[c]
        s4.v[c] = st.v[c] + dtau * dv3[c]
        c = c + 1
    }

    var dx4: [f64; 4] = [0.0; 4]
    var dv4: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, &s4, &mut dx4, &mut dv4)

    c = 0
    while c < dim {
        st.x[c] = st.x[c] + dtau / 6.0 * (dx1[c] + 2.0 * dx2[c] + 2.0 * dx3[c] + dx4[c])
        st.v[c] = st.v[c] + dtau / 6.0 * (dv1[c] + 2.0 * dv2[c] + 2.0 * dv3[c] + dv4[c])
        c = c + 1
    }
    st.tau = st.tau + dtau
