        x_train: [0.0; 128],
        alpha: [0.0; 128],
        n_train: 0,
        length_scale: 0.0,
        kernel_type: 0;
    }
    rkhs_train(&x_train, &y_train, n_pts, 1.0, 0, 1.0e-10, &!model);

    let nm = rkhs_norm(&model);
    nm >= 0.0 - 1.0e-10;
}

