    }
}

fn mr_matvec(A: &[f64; 4096], x: &[f64; 4096], x_off: i32,
             m: i32, n: i32,
             y: &![f64; 4096], y_off: i32) with Mut, Div, Panic {
    let mut i = 0
    while i < m {
        let mut sum = 0.0
        let mut j = 0
        while j < n {
            sum = sum + A[i * n + j] * x[x_off + j]
            j = j + 1
        }
        y[y_off + i] = sum
        i = i + 1
    }
}

fn mr_matvec_mixed(A: &[f64; 4096], x: &[f64; 64],
                   m: i32, n: i32,
                   y: &![f64; 256]) with Mut, Div, Panic {
    let mut i = 0
    while i < m {
        let mut sum = 0.0
        let mut j = 0
        while j < n {
            sum = sum + A[i * n + j] * x[j]
            j = j + 1
        }
        y[i] = sum
        i = i + 1
    }
}

fn mr_mat_mul(A: &[f64; 4096], B: &[f64; 4096],
              m: i32, k: i32, n: i32,
              C: &![f64; 4096]) with Mut, Div, Panic {
    let mut i = 0
    while i < m {
        let mut j = 0
        while j < n {
            let mut sum = 0.0
            let mut p = 0
            while p < k {
                sum = sum + A[i * k + p] * B[p * n + j]
                p = p + 1
            }
            C[i * n + j] = sum
            j = j + 1
        }
        i = i + 1
    }
}

fn mr_transpose(A: &[f64; 4096], m: i32, n: i32, At: &![f64; 4096]) with Mut, Div, Panic {
    let mut i = 0
    while i < m {
        let mut j = 0
        while j < n {
            At[j * m + i] = A[i * n + j]
            j = j + 1
        }
        i = i + 1
    }
}

fn mr_argmax_abs_col(A: &[f64; 4096], m: i32, n: i32, col: i32, start_row: i32) -> i32 with Mut, Div, Panic {
    let mut best_idx = start_row
    let mut best_val = mr_abs(A[start_row * n + col])
    let mut i = start_row + 1
    while i < m {
        let v = mr_abs(A[i * n + col])
        if v > best_val {
            best_val = v
            best_idx = i
        }
        i = i + 1
    }
    best_idx
}

fn mr_argmax_abs_256(v: &[f64; 256], n: i32) -> i32 with Mut, Div, Panic {
    let mut best_idx = 0
    let mut best_val = mr_abs(v[0])
    let mut i = 1
    while i < n {
        let a = mr_abs(v[i])
        if a > best_val {
            best_val = a
            best_idx = i
        }
        i = i + 1
    }
    best_idx
}

