// ============================================================================
// ONE-SIDED JACOBI SVD (copied from mor.sio)
// ============================================================================

fn mr_svd(A: &[f64; 4096], m: i32, n: i32,
          U: &![f64; 4096], S: &![f64; 64], Vt: &![f64; 4096]) with Mut, Div, Panic {

    let mut B: [f64; 4096] = [0.0; 4096]
    let mut i = 0
    while i < n {
        let mut j = 0
        while j < n {
            let mut sum = 0.0
            let mut k = 0
            while k < m {
                sum = sum + A[k * n + i] * A[k * n + j]
                k = k + 1
            }
            B[i * n + j] = sum
            j = j + 1
        }
        i = i + 1
    }

    let mut V: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < n {
        V[i * n + i] = 1.0
        i = i + 1
    }

    let max_sweeps = 100
    let tol = 1.0e-12
    let mut sweep = 0
    while sweep < max_sweeps {
        let mut off_norm = 0.0
        let mut p = 0
        while p < n {
            let mut q = p + 1
            while q < n {
                off_norm = off_norm + B[p * n + q] * B[p * n + q]
                q = q + 1
            }
            p = p + 1
        }
        if off_norm < tol * tol {
            sweep = max_sweeps
        } else {
            p = 0
            while p < n {
                let mut q = p + 1
                while q < n {
                    let bpq = B[p * n + q]
                    if mr_abs(bpq) > 1.0e-15 {
                        let bpp = B[p * n + p]
                        let bqq = B[q * n + q]
                        let tau = (bqq - bpp) / (2.0 * bpq)
                        let mut t = 0.0
                        if mr_abs(tau) > 1.0e30 {
                            t = 1.0 / (2.0 * tau)
                        } else {
                            let sign_tau = if tau >= 0.0 { 1.0 } else { 0.0 - 1.0 }
                            t = sign_tau / (mr_abs(tau) + mr_sqrt(1.0 + tau * tau))
                        }
                        let c = 1.0 / mr_sqrt(1.0 + t * t)
                        let s = t * c

                        let mut k = 0
                        while k < n {
                            let bp = B[k * n + p]
                            let bq = B[k * n + q]
                            B[k * n + p] = c * bp - s * bq
                            B[k * n + q] = s * bp + c * bq
                            k = k + 1
                        }
                        k = 0
                        while k < n {
                            let bp = B[p * n + k]
                            let bq = B[q * n + k]
                            B[p * n + k] = c * bp - s * bq
                            B[q * n + k] = s * bp + c * bq
                            k = k + 1
                        }
                        B[p * n + q] = 0.0
                        B[q * n + p] = 0.0

                        k = 0
                        while k < n {
                            let vp = V[k * n + p]
                            let vq = V[k * n + q]
                            V[k * n + p] = c * vp - s * vq
                            V[k * n + q] = s * vp + c * vq
                            k = k + 1
                        }
                    }
                    q = q + 1
                }
                p = p + 1
            }
            sweep = sweep + 1
        }
    }

    let mut eig: [f64; 64] = [0.0; 64]
    let mut order: [i32; 64] = [0; 64]
    i = 0
    while i < n {
        eig[i] = B[i * n + i]
        if eig[i] < 0.0 { eig[i] = 0.0 }
        order[i] = i
        i = i + 1
    }

    i = 1
    while i < n {
        let key_val = eig[i]
        let key_idx = order[i]
        let mut j = i - 1
        let mut done = false
        while j >= 0 && done == false {
            if eig[j] < key_val {
                eig[j + 1] = eig[j]
                order[j + 1] = order[j]
                j = j - 1
            } else {
                done = true
            }
        }
        eig[j + 1] = key_val
        order[j + 1] = key_idx
        i = i + 1
    }

    i = 0
    while i < n {
        S[i] = mr_sqrt(eig[i])
        i = i + 1
    }

    i = 0
    while i < n {
        let mut j = 0
        while j < n {
            Vt[i * n + j] = V[j * n + order[i]]
            j = j + 1
        }
        i = i + 1
    }

    let mut Vs: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < n {
        let mut j = 0
        while j < n {
            Vs[j * n + i] = Vt[i * n + j]
            j = j + 1
        }
        i = i + 1
    }

    i = 0
    while i < n {
        if S[i] > 1.0e-14 {
            let inv_s = 1.0 / S[i]
            let mut r = 0
            while r < m {
                let mut sum = 0.0
                let mut c = 0
                while c < n {
                    sum = sum + A[r * n + c] * Vs[c * n + i]
                    c = c + 1
                }
                U[r * n + i] = sum * inv_s
                r = r + 1
            }
        } else {
            let mut r = 0
            while r < m {
                U[r * n + i] = 0.0
                r = r + 1
            }
        }
        i = i + 1
    }
}

// ============================================================================
// POD (copied from mor.sio)
// ============================================================================

fn pod_rank_for_energy(sv: &[f64; 64], n: i32, energy_frac: f64) -> i32 with Mut, Div, Panic {
    let mut total = 0.0
    let mut i = 0
    while i < n {
        total = total + sv[i] * sv[i]
        i = i + 1
    }

    if total < 1.0e-30 { return 1 }

    let mut cumul = 0.0
    let mut r = 0
    while r < n {
        cumul = cumul + sv[r] * sv[r]
        if cumul / total >= energy_frac { return r + 1 }
        r = r + 1
    }
    n
}

fn pod_compute(snapshots: &SnapshotMatrix, energy_thresh: f64,
               basis: &!ReducedBasis) with Mut, Div, Panic {
    let nd = snapshots.n_dof
    let ns = snapshots.n_snap

    // Copy snapshots.data to local array: &ref.field passing is broken in lean_single
    let mut data_local: [f64; 4096] = [0.0; 4096]
    let mut di = 0
    while di < nd * ns { data_local[di] = snapshots.data[di]; di = di + 1 }

    let mut U_svd: [f64; 4096] = [0.0; 4096]
    let mut S_svd: [f64; 64] = [0.0; 64]
    let mut Vt_svd: [f64; 4096] = [0.0; 4096]

    mr_svd(&data_local, nd, ns, &!U_svd, &!S_svd, &!Vt_svd)

    let r = pod_rank_for_energy(&S_svd, ns, energy_thresh)

    let mut i = 0
    while i < nd {
        let mut j = 0
        while j < r {
            basis.V[i * r + j] = U_svd[i * ns + j]
            j = j + 1
        }
        i = i + 1
    }

    basis.n_dof = nd
    basis.n_basis = r

    i = 0
    while i < ns {
        basis.singular_values[i] = S_svd[i]
        i = i + 1
    }
}

// ============================================================================
// GALERKIN PROJECTION (copied from mor.sio)
// ============================================================================

fn mor_project_matrix(V: &[f64; 4096], A: &[f64; 4096],
                      n_dof: i32, n_basis: i32,
                      A_r: &![f64; 4096]) with Mut, Div, Panic {
    let mut AV: [f64; 4096] = [0.0; 4096]
    let mut i = 0
    while i < n_dof {
        let mut j = 0
        while j < n_basis {
            let mut sum = 0.0
            let mut k = 0
            while k < n_dof {
                sum = sum + A[i * n_dof + k] * V[k * n_basis + j]
                k = k + 1
            }
            AV[i * n_basis + j] = sum
            j = j + 1
        }
        i = i + 1
    }

    i = 0
    while i < n_basis {
        let mut j = 0
        while j < n_basis {
            let mut sum = 0.0
            let mut k = 0
            while k < n_dof {
                sum = sum + V[k * n_basis + i] * AV[k * n_basis + j]
                k = k + 1
            }
            A_r[i * n_basis + j] = sum
            j = j + 1
        }
        i = i + 1
    }
}

fn mor_project_vector(V: &[f64; 4096], b: &[f64; 256],
                      n_dof: i32, n_basis: i32,
                      b_r: &![f64; 64]) with Mut, Div, Panic {
    let mut i = 0
    while i < n_basis {
        let mut sum = 0.0
        let mut k = 0
        while k < n_dof {
            sum = sum + V[k * n_basis + i] * b[k]
            k = k + 1
        }
        b_r[i] = sum
        i = i + 1
    }
}

fn mor_project_rhs(V: &[f64; 4096], f: &[f64; 256],
                   n_dof: i32, n_basis: i32,
                   f_r: &![f64; 64]) with Mut, Div, Panic {
    mor_project_vector(V, f, n_dof, n_basis, f_r)
}

// ============================================================================
// RECONSTRUCTION (copied from mor.sio)
// ============================================================================

fn mor_reconstruct(V: &[f64; 4096], u_red: &[f64; 64],
                   n_dof: i32, n_basis: i32,
                   u_full: &![f64; 256]) with Mut, Div, Panic {
    let mut i = 0
    while i < n_dof {
        let mut sum = 0.0
        let mut j = 0
        while j < n_basis {
            sum = sum + V[i * n_basis + j] * u_red[j]
            j = j + 1
        }
        u_full[i] = sum
        i = i + 1
    }
}

// ============================================================================
// REDUCED SYSTEM SOLVE (copied from mor.sio)
// ============================================================================

fn mor_solve_reduced(A_r: &[f64; 4096], b_r: &[f64; 64], n_basis: i32,
                     u_r: &![f64; 64]) with Mut, Div, Panic {
    let nb = n_basis

    let mut M: [f64; 4096] = [0.0; 4096]
    let mut rhs: [f64; 64] = [0.0; 64]
    let mut i = 0
    while i < nb {
        let mut j = 0
        while j < nb {
            M[i * nb + j] = A_r[i * nb + j]
            j = j + 1
        }
        rhs[i] = b_r[i]
        i = i + 1
    }

    let mut col = 0
    while col < nb {
        let mut pivot_row = col
        let mut pivot_val = mr_abs(M[col * nb + col])
        let mut row = col + 1
        while row < nb {
            let v = mr_abs(M[row * nb + col])
            if v > pivot_val {
                pivot_val = v
                pivot_row = row
            }
            row = row + 1
        }

        if pivot_row != col {
            let mut k = 0
            while k < nb {
                let tmp = M[col * nb + k]
                M[col * nb + k] = M[pivot_row * nb + k]
                M[pivot_row * nb + k] = tmp
                k = k + 1
            }
            let tmp_r = rhs[col]
            rhs[col] = rhs[pivot_row]
            rhs[pivot_row] = tmp_r
        }

        let diag = M[col * nb + col]
        if mr_abs(diag) < 1.0e-30 {
            col = col + 1
        } else {
            row = col + 1
            while row < nb {
                let factor = M[row * nb + col] / diag
                let mut k = col + 1
                while k < nb {
                    M[row * nb + k] = M[row * nb + k] - factor * M[col * nb + k]
                    k = k + 1
                }
                M[row * nb + col] = 0.0
                rhs[row] = rhs[row] - factor * rhs[col]
                row = row + 1
            }
            col = col + 1
        }
    }

    i = nb - 1
    let mut done_back = false
    while i >= 0 && done_back == false {
        let mut sum = rhs[i]
        let mut j = i + 1
        while j < nb {
            sum = sum - M[i * nb + j] * u_r[j]
            j = j + 1
        }
        let diag = M[i * nb + i]
        if mr_abs(diag) < 1.0e-30 {
            u_r[i] = 0.0
        } else {
            u_r[i] = sum / diag
        }
        if i == 0 { done_back = true } else { i = i - 1 }
    }
}

// ============================================================================
// ERROR ESTIMATION (copied from mor.sio)
// ============================================================================

fn mor_error_estimate(A: &[f64; 4096], b: &[f64; 256], V: &[f64; 4096],
                      u_red: &[f64; 64],
                      n_dof: i32, n_basis: i32) -> f64 with Mut, Div, Panic {
    let mut u_full: [f64; 256] = [0.0; 256]
    mor_reconstruct(V, u_red, n_dof, n_basis, &!u_full)

    let mut res: [f64; 256] = [0.0; 256]
    let mut i = 0
    while i < n_dof {
        let mut sum = 0.0
        let mut j = 0
        while j < n_dof {
            sum = sum + A[i * n_dof + j] * u_full[j]
            j = j + 1
        }
        res[i] = b[i] - sum
        i = i + 1
    }

    let res_norm = mr_norm2_256(&res, n_dof)
    let b_norm = mr_norm2_256(b, n_dof)

    if b_norm < 1.0e-30 { return res_norm }
    res_norm / b_norm
}

fn mor_true_error(u_full_exact: &[f64; 256], u_full_approx: &[f64; 256],
                  n_dof: i32) -> f64 with Mut, Div, Panic {
    let mut diff_sq = 0.0
    let mut exact_sq = 0.0
    let mut i = 0
    while i < n_dof {
        let d = u_full_exact[i] - u_full_approx[i]
        diff_sq = diff_sq + d * d
        exact_sq = exact_sq + u_full_exact[i] * u_full_exact[i]
        i = i + 1
    }

    if exact_sq < 1.0e-30 { return mr_sqrt(diff_sq) }
    mr_sqrt(diff_sq) / mr_sqrt(exact_sq)
}

// ============================================================================
// FULL MOR PIPELINE (copied from mor.sio)
// ============================================================================

fn mor_solve(A: &[f64; 4096], b: &[f64; 256], n_dof: i32,
             basis: &ReducedBasis,
             result: &!MORResult) with Mut, Div, Panic {
    let nb = basis.n_basis

    // Copy basis.V to local: &ref.field passing is broken in lean_single
    let mut V_local: [f64; 4096] = [0.0; 4096]
    let mut vi = 0
    while vi < n_dof * nb { V_local[vi] = basis.V[vi]; vi = vi + 1 }

    let mut A_r: [f64; 4096] = [0.0; 4096]
    mor_project_matrix(&V_local, A, n_dof, nb, &!A_r)

    let mut b_r: [f64; 64] = [0.0; 64]
    mor_project_rhs(&V_local, b, n_dof, nb, &!b_r)

    let mut u_r: [f64; 64] = [0.0; 64]
    mor_solve_reduced(&A_r, &b_r, nb, &!u_r)

    let mut i = 0
    while i < nb {
        result.u_reduced[i] = u_r[i]
        i = i + 1
    }

    // Reconstruct into local array then copy: &!ref.field is also broken
    let mut u_full_local: [f64; 256] = [0.0; 256]
    mor_reconstruct(&V_local, &u_r, n_dof, nb, &!u_full_local)
    i = 0
    while i < n_dof { result.u_full[i] = u_full_local[i]; i = i + 1 }

    let err = mor_error_estimate(A, b, &V_local, &u_r, n_dof, nb)

    result.n_basis = nb
    result.error_est = err
    result.converged = err < 1.0e-6
}

// ============================================================================
// GRAM-SCHMIDT (copied from mor.sio)
// ============================================================================

fn mr_gram_schmidt(V: &![f64; 4096], n_dof: i32, n_basis: i32,
                   v_new: &[f64; 256]) with Mut, Div, Panic {
    let mut w: [f64; 256] = [0.0; 256]
    let mut i = 0
    while i < n_dof {
        w[i] = v_new[i]
        i = i + 1
    }

    // Read existing columns at new stride (n_basis+1) since we write at that stride too
    let mut pass = 0
    while pass < 2 {
        let mut j = 0
        while j < n_basis {
            let mut proj = 0.0
            i = 0
            while i < n_dof {
                proj = proj + w[i] * V[i * (n_basis + 1) + j]
                i = i + 1
            }
            i = 0
            while i < n_dof {
                w[i] = w[i] - proj * V[i * (n_basis + 1) + j]
                i = i + 1
            }
            j = j + 1
        }
        pass = pass + 1
    }

    let nrm = mr_norm2_256(&w, n_dof)
    if nrm < 1.0e-14 {
        i = 0
        while i < n_dof {
            V[i * (n_basis + 1) + n_basis] = 0.0
            i = i + 1
        }
        return
    }

    let inv_nrm = 1.0 / nrm

    i = 0
    while i < n_dof {
        V[i * (n_basis + 1) + n_basis] = w[i] * inv_nrm
        i = i + 1
    }
}

// ============================================================================
// DEIM (copied from mor.sio)
// ============================================================================

fn deim_compute(basis: &ReducedBasis, deim: &!DEIMBasis) with Mut, Div, Panic {
    let nd = basis.n_dof
    let mut m = basis.n_basis
    if m > 64 { m = 64 }

    let mut i = 0
    while i < nd {
        let mut j = 0
        while j < m {
            deim.U[i * m + j] = basis.V[i * basis.n_basis + j]
            j = j + 1
        }
        i = i + 1
    }
    deim.n_dof = nd
    deim.n_deim = m

    let mut u_col: [f64; 256] = [0.0; 256]
    i = 0
    while i < nd {
        u_col[i] = deim.U[i * m + 0]
        i = i + 1
    }
    deim.P[0] = mr_argmax_abs_256(&u_col, nd)

    let mut l = 1
    while l < m {
        i = 0
        while i < nd {
            u_col[i] = deim.U[i * m + l]
            i = i + 1
        }

        let mut PtU: [f64; 4096] = [0.0; 4096]
        let mut Ptu: [f64; 64] = [0.0; 64]
        i = 0
        while i < l {
            let pi = deim.P[i]
            let mut j = 0
            while j < l {
                PtU[i * l + j] = deim.U[pi * m + j]
                j = j + 1
            }
            Ptu[i] = u_col[pi]
            i = i + 1
        }

        let mut c_vec: [f64; 64] = [0.0; 64]

        let mut M_d: [f64; 4096] = [0.0; 4096]
        let mut rhs_d: [f64; 64] = [0.0; 64]
        i = 0
        while i < l {
            let mut j = 0
            while j < l {
                M_d[i * l + j] = PtU[i * l + j]
                j = j + 1
            }
            rhs_d[i] = Ptu[i]
            i = i + 1
        }

        let mut col = 0
        while col < l {
            let mut pivot_row = col
            let mut pivot_val = mr_abs(M_d[col * l + col])
            let mut row = col + 1
            while row < l {
                let v = mr_abs(M_d[row * l + col])
                if v > pivot_val { pivot_val = v; pivot_row = row }
                row = row + 1
            }
            if pivot_row != col {
                let mut k = 0
                while k < l {
                    let tmp = M_d[col * l + k]
                    M_d[col * l + k] = M_d[pivot_row * l + k]
                    M_d[pivot_row * l + k] = tmp
                    k = k + 1
                }
                let tmp_r = rhs_d[col]
                rhs_d[col] = rhs_d[pivot_row]
                rhs_d[pivot_row] = tmp_r
            }

            let diag = M_d[col * l + col]
            if mr_abs(diag) > 1.0e-30 {
                row = col + 1
                while row < l {
                    let factor = M_d[row * l + col] / diag
                    let mut k = col + 1
                    while k < l {
                        M_d[row * l + k] = M_d[row * l + k] - factor * M_d[col * l + k]
                        k = k + 1
                    }
                    rhs_d[row] = rhs_d[row] - factor * rhs_d[col]
                    row = row + 1
                }
            }
            col = col + 1
        }

        i = l - 1
        let mut done_bs = false
        while i >= 0 && done_bs == false {
            let mut sum = rhs_d[i]
            let mut j = i + 1
            while j < l {
                sum = sum - M_d[i * l + j] * c_vec[j]
                j = j + 1
            }
            let diag = M_d[i * l + i]
            if mr_abs(diag) > 1.0e-30 {
                c_vec[i] = sum / diag
            } else {
                c_vec[i] = 0.0
            }
            if i == 0 { done_bs = true } else { i = i - 1 }
        }

        let mut res: [f64; 256] = [0.0; 256]
        i = 0
        while i < nd {
            let mut val = u_col[i]
            let mut j = 0
            while j < l {
                val = val - deim.U[i * m + j] * c_vec[j]
                j = j + 1
            }
            res[i] = val
            i = i + 1
        }

        deim.P[l] = mr_argmax_abs_256(&res, nd)

        l = l + 1
    }
}

fn deim_approximate(deim: &DEIMBasis, f_full: &[f64; 256],
                    f_approx: &![f64; 256]) with Mut, Div, Panic {
    let nd = deim.n_dof
    let m = deim.n_deim

    let mut f_P: [f64; 64] = [0.0; 64]
