    let mut rhs_d: [f64; 64] = [0.0; 64]
    i = 0
    while i < m {
        let mut j = 0
        while j < m {
            M_d[i * m + j] = PtU[i * m + j]
            j = j + 1
        }
        rhs_d[i] = f_P[i]
        i = i + 1
    }

    let mut col = 0
    while col < m {
        let mut pivot_row = col
        let mut pivot_val = mr_abs(M_d[col * m + col])
        let mut row = col + 1
        while row < m {
            let v = mr_abs(M_d[row * m + col])
            if v > pivot_val { pivot_val = v; pivot_row = row }
            row = row + 1
        }
        if pivot_row != col {
            let mut k = 0
            while k < m {
                let tmp = M_d[col * m + k]
                M_d[col * m + k] = M_d[pivot_row * m + k]
                M_d[pivot_row * m + k] = tmp
                k = k + 1
            }
            let tmp_r = rhs_d[col]
            rhs_d[col] = rhs_d[pivot_row]
            rhs_d[pivot_row] = tmp_r
        }

        let diag = M_d[col * m + col]
        if mr_abs(diag) > 1.0e-30 {
            row = col + 1
            while row < m {
                let factor = M_d[row * m + col] / diag
                let mut k = col + 1
                while k < m {
                    M_d[row * m + k] = M_d[row * m + k] - factor * M_d[col * m + k]
                    k = k + 1
                }
                rhs_d[row] = rhs_d[row] - factor * rhs_d[col]
                row = row + 1
            }
        }
        col = col + 1
    }

    i = m - 1
    let mut done_bs = false
    while i >= 0 && done_bs == false {
        let mut sum = rhs_d[i]
        let mut j = i + 1
        while j < m {
            sum = sum - M_d[i * m + j] * c_vec[j]
            j = j + 1
        }
        let diag = M_d[i * m + i]
        if mr_abs(diag) > 1.0e-30 {
            c_vec[i] = sum / diag
        } else {
            c_vec[i] = 0.0
        }
        if i == 0 { done_bs = true } else { i = i - 1 }
    }

    i = 0
    while i < nd {
        let mut sum = 0.0
        let mut j = 0
        while j < m {
            sum = sum + deim.U[i * m + j] * c_vec[j]
            j = j + 1
        }
        f_approx[i] = sum
        i = i + 1
    }
}

// ============================================================================
// DIRECT FULL-SYSTEM SOLVE (Gaussian elimination for tests)
// ============================================================================

fn direct_solve(A: &[f64; 4096], b: &[f64; 256], n: i32,
                x: &![f64; 256]) with Mut, Div, Panic {
    let mut M: [f64; 4096] = [0.0; 4096]
    let mut rhs: [f64; 256] = [0.0; 256]
    let mut i = 0
    while i < n {
        let mut j = 0
        while j < n {
            M[i * n + j] = A[i * n + j]
            j = j + 1
        }
        rhs[i] = b[i]
        i = i + 1
    }

    let mut col = 0
    while col < n {
        let mut pivot_row = col
        let mut pivot_val = mr_abs(M[col * n + col])
        let mut row = col + 1
        while row < n {
            let v = mr_abs(M[row * n + col])
            if v > pivot_val { pivot_val = v; pivot_row = row }
            row = row + 1
        }
        if pivot_row != col {
            let mut k = 0
            while k < n {
                let tmp = M[col * n + k]
                M[col * n + k] = M[pivot_row * n + k]
                M[pivot_row * n + k] = tmp
                k = k + 1
            }
            let tmp_r = rhs[col]
            rhs[col] = rhs[pivot_row]
            rhs[pivot_row] = tmp_r
        }
        let diag = M[col * n + col]
        if mr_abs(diag) > 1.0e-30 {
            row = col + 1
            while row < n {
                let factor = M[row * n + col] / diag
                let mut k = col + 1
                while k < n {
                    M[row * n + k] = M[row * n + k] - factor * M[col * n + k]
                    k = k + 1
                }
                M[row * n + col] = 0.0
                rhs[row] = rhs[row] - factor * rhs[col]
                row = row + 1
            }
        }
        col = col + 1
    }

    i = n - 1
    let mut done_back = false
    while i >= 0 && done_back == false {
        let mut sum = rhs[i]
        let mut j = i + 1
        while j < n {
            sum = sum - M[i * n + j] * x[j]
            j = j + 1
        }
        let diag = M[i * n + i]
        if mr_abs(diag) < 1.0e-30 {
            x[i] = 0.0
        } else {
            x[i] = sum / diag
        }
        if i == 0 { done_back = true } else { i = i - 1 }
    }
}

