fn mr_svd(A: &[f64; 4096], m: i32, n: i32,
          U: &![f64; 4096], S: &![f64; 64], Vt: &![f64; 4096]) with Mut, Div, Panic {

    var B: [f64; 4096] = [0.0; 4096]
    var i = 0
    while i < n {
        var j = 0
        while j < n {
            var sum = 0.0
            var k = 0
            while k < m {
                sum = sum + A[k * n + i] * A[k * n + j]
                k = k + 1
            }
            B[i * n + j] = sum
            j = j + 1
        }
        i = i + 1
    }

    var V: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < n {
        V[i * n + i] = 1.0
        i = i + 1
    }

    let max_sweeps = 100
    let tol = 1.0e-12
    var sweep = 0
    while sweep < max_sweeps {
        var off_norm = 0.0
        var p = 0
        while p < n {
            var q = p + 1
            while q < n {
                off_norm = off_norm + B[p * n + q] * B[p * n + q]
                q = q + 1
            }
            p = p + 1
        }
        if off_norm < tol * tol {
            sweep = max_sweeps
        } else {
            p = 0
            while p < n {
                var q = p + 1
                while q < n {
                    let bpq = B[p * n + q]
                    if mr_abs(bpq) > 1.0e-15 {
                        let bpp = B[p * n + p]
                        let bqq = B[q * n + q]
                        let tau = (bqq - bpp) / (2.0 * bpq)
                        var t = 0.0
                        if mr_abs(tau) > 1.0e30 {
                            t = 1.0 / (2.0 * tau)
                        } else {
                            let sign_tau = if tau >= 0.0 { 1.0 } else { 0.0 - 1.0 }
                            t = sign_tau / (mr_abs(tau) + mr_sqrt(1.0 + tau * tau))
                        }
                        let c = 1.0 / mr_sqrt(1.0 + t * t)
                        let s = t * c

                        var k = 0
                        while k < n {
                            let bp = B[k * n + p]
                            let bq = B[k * n + q]
                            B[k * n + p] = c * bp - s * bq
                            B[k * n + q] = s * bp + c * bq
                            k = k + 1
                        }
                        k = 0
                        while k < n {
                            let bp = B[p * n + k]
                            let bq = B[q * n + k]
                            B[p * n + k] = c * bp - s * bq
                            B[q * n + k] = s * bp + c * bq
                            k = k + 1
                        }
                        B[p * n + q] = 0.0
                        B[q * n + p] = 0.0

                        k = 0
                        while k < n {
                            let vp = V[k * n + p]
                            let vq = V[k * n + q]
                            V[k * n + p] = c * vp - s * vq
                            V[k * n + q] = s * vp + c * vq
                            k = k + 1
                        }
                    }
                    q = q + 1
                }
                p = p + 1
            }
            sweep = sweep + 1
        }
    }

    var eig: [f64; 64] = [0.0; 64]
    var order: [i32; 64] = [0; 64]
    i = 0
    while i < n {
        eig[i] = B[i * n + i]
        if eig[i] < 0.0 { eig[i] = 0.0 }
        order[i] = i
        i = i + 1
    }

    i = 1
    while i < n {
        let key_val = eig[i]
        let key_idx = order[i]
        var j = i - 1
        var done = false
        while j >= 0 && done == false {
            if eig[j] < key_val {
                eig[j + 1] = eig[j]
                order[j + 1] = order[j]
                j = j - 1
            } else {
                done = true
            }
        }
        eig[j + 1] = key_val
        order[j + 1] = key_idx
        i = i + 1
    }

    i = 0
    while i < n {
        S[i] = mr_sqrt(eig[i])
        i = i + 1
    }

    i = 0
    while i < n {
        var j = 0
        while j < n {
            Vt[i * n + j] = V[j * n + order[i]]
            j = j + 1
        }
        i = i + 1
    }

    var Vs: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < n {
        var j = 0
        while j < n {
            Vs[j * n + i] = Vt[i * n + j]
            j = j + 1
        }
        i = i + 1
    }

    i = 0
    while i < n {
        if S[i] > 1.0e-14 {
            let inv_s = 1.0 / S[i]
            var r = 0
            while r < m {
                var sum = 0.0
                var c = 0
                while c < n {
                    sum = sum + A[r * n + c] * Vs[c * n + i]
                    c = c + 1
                }
                U[r * n + i] = sum * inv_s
                r = r + 1
            }
        } else {
            var r = 0
            while r < m {
                U[r * n + i] = 0.0
                r = r + 1
            }
        }
        i = i + 1
    }
}

// ============================================================================
// POD (copied from mor.sio)
// ============================================================================

fn pod_rank_for_energy(sv: &[f64; 64], n: i32, energy_frac: f64) -> i32 with Mut, Div, Panic {
    var total = 0.0
    var i = 0
    while i < n {
        total = total + sv[i] * sv[i]
        i = i + 1
    }

    if total < 1.0e-30 { return 1 }

    var cumul = 0.0
    var r = 0
    while r < n {
        cumul = cumul + sv[r] * sv[r]
        if cumul / total >= energy_frac { return r + 1 }
        r = r + 1
    }
    n
}

fn pod_compute(snapshots: &SnapshotMatrix, energy_thresh: f64,
               basis: &!ReducedBasis) with Mut, Div, Panic {
    let nd = snapshots.n_dof
    let ns = snapshots.n_snap

    // Copy snapshots.data to local array: &ref.field passing is broken in lean_single
    var data_local: [f64; 4096] = [0.0; 4096]
    var di = 0
    while di < nd * ns { data_local[di] = snapshots.data[di]; di = di + 1 }

    var U_svd: [f64; 4096] = [0.0; 4096]
    var S_svd: [f64; 64] = [0.0; 64]
    var Vt_svd: [f64; 4096] = [0.0; 4096]

    mr_svd(&data_local, nd, ns, &!U_svd, &!S_svd, &!Vt_svd)

    let r = pod_rank_for_energy(&S_svd, ns, energy_thresh)

    var i = 0
    while i < nd {
        var j = 0
        while j < r {
            basis.V[i * r + j] = U_svd[i * ns + j]
            j = j + 1
        }
        i = i + 1
    }

    basis.n_dof = nd
    basis.n_basis = r

    i = 0
    while i < ns {
        basis.singular_values[i] = S_svd[i]
        i = i + 1
    }
}

