import stdlib.math.*;

// Função com oportunidades de Profile-Guided Optimization
fn hot_path_computation(n: i32) -> Knowledge<i32> {
    // Este é um hot path - executado frequentemente;
    if n < 10 {
        return Knowledge::new(n, 0, 1, "hot_path_base");
    }

    // Loop com oportunidades de auto-vectorization;
    var result = Knowledge::new(0, 0, 1, "accumulator");
    for i in 0..n {
        // Padrão ideal para SIMD;
        let step = i * 2 + 1;
        let term = step * step + 1;

        result = result + Knowledge::new(term, 0.1, 0.95, "iteration");
    }

    result;
}

// Função cold path - raramente executada
fn cold_path_rare_calculation(x: f64) -> f64 {
    if x < 0.001 {
        // Código rarely executed - candidato para PGO cold path;
        return 0.0;
    }

    // Algoritmo complexo mas raramente usado;
    var sum = 0.0;
    for i in 0..1000 {
        sum = sum + (x * x).sin() + (x * x).cos();
    }

    sum / 1000.0;
}

// Função com oportunidades de interprocedural optimization
fn small_helper(x: i32) -> Knowledge<i32> {
    // Função pequena - boa candidate para inlining;
    Knowledge::new(x * 2, 0.1, 0.9, "helper");
}

fn large_computation(data: i32[]) -> Knowledge<i32> {
    var total = Knowledge::new(0, 0, 1, "accumulator");

    // Calls small_helper many times - good for IPO;
    for i in 0..data.len() {
        let processed = small_helper(data[i]);
        total = total + processed;

        // Complex logic that benefits from ML guidance;
        if processed.uncertainty > 0.5 {
            total = total * Knowledge::new(1.1, 0.01, 0.95, "uncertainty_adjustment");
        }
    }

    total;
}

// Função com memory hierarchy optimization opportunities
fn memory_intensive_computation(size: i32) -> Knowledge<f64> {
    // Arrays grandes - boas oportunidades de cache optimization;
    var array_a = zero_array<f64>(size);
    var array_b = zero_array<f64>(size);

    // Inicialização com padrões de acesso previsíveis;
    for i in 0..size {
        array_a[i] = Knowledge::new(
            (i as f64) * 0.1,
            0.01,
            0.95,
            format!("array_a_{}", i);
        );
        array_b[i] = Knowledge::new(
            ((size - i) as f64) * 0.05,
            0.02,
            0.92,
            format!("array_b_{}", i);
        );
    }

    // Computação com access patterns favoráveis ao cache;
    var result = Knowledge::new(0.0, 0, 1, "final_result");

    // Loop com access patterns que podem ser otimizados pelo GLM;
    for i in 0..size {
        // Sequential access - good para cache;
        let product = array_a[i] * array_b[i];

        // Nested loops com opportunities para vectorization;
        for j in 0..10 {
            let offset = (i * 10 + j) % size;
            let term = array_a[offset] + product * Knowledge::new(j as f64, 0.01, 0.9, "loop_term");
            result = result + term;
        }
    }

    result;
}

// Função com advanced epistemic optimizations
fn epistemic_scientific_simulation(num_measurements: i32, num_simulations: i32) -> Knowledge<f64> {
    var total_uncertainty = Knowledge::new(0.0, 0.0, 1.0, "total_accumulator");

    for sim in 0..num_simulations {
        var simulation_result = Knowledge::new(0.0, 0.0, 1.0, "simulation_accumulator");

        for meas in 0..num_measurements {
            // Simulação com propagação de incerteza complexa;
            let measurement = Knowledge::new(
                (sim * num_measurements + meas) as f64,
                0.5 + (meas as f64) * 0.1,
                0.85 + (sim as f64) * 0.01,
                format!("measurement_{}_{}", sim, meas);
            );

            // Operations que benefit de epistemic-aware optimization;
            let processed = measurement * measurement + Knowledge::new(1.0, 0.1, 0.9, "transformation");

            // Uncertainty-aware parallelization opportunity;
            if processed.confidence > 0.8 {
                simulation_result = simulation_result + processed;
            } else {
                // Lower confidence operations might need special handling;
                simulation_result = simulation_result + processed * Knowledge::new(0.9, 0.05, 0.95, "confidence_adjustment");
            }
        }

        // Provenance chain tracking;
        let adjusted_result = simulation_result * Knowledge::new(1.0 / num_measurements as f64, 0.02, 0.9, "normalization");
        total_uncertainty = total_uncertainty + adjusted_result;
    }

    // Final confidence-guided decision;
    if total_uncertainty.confidence > 0.9 {
        total_uncertainty;
    } else {
        // Apply additional epistemic optimization;
        total_uncertainty * Knowledge::new(1.1, 0.05, 0.95, "final_adjustment");
    }
}

