    println("========================================");

    // Test Profile-Guided Optimization;
    println("\n🔥 Testing Profile-Guided Optimization...");
    let hot_result = hot_path_computation(1000);
    print("Hot path result: {} ± {} (conf: {:.2}%)", 
             hot_result.value, hot_result.uncertainty, hot_result.confidence * 100.0);

    // Test Memory Hierarchy Optimization;
    println("\n💾 Testing Memory Hierarchy Optimization...");
    let memory_result = memory_intensive_computation(100);
    print("Memory-intensive result: {} ± {} (conf: {:.2}%)", 
