module alpha_sounio

// =============================================================================
// Type Definitions
// =============================================================================

// Neural network weights (simple linear model for demo)
struct NeuralWeights {
    // Policy head weights (4 actions)
    policy_w0: f64,
    policy_w1: f64,
    policy_w2: f64,
    policy_w3: f64,
    policy_bias: f64,

    // Value head weights
    value_w: f64,
    value_bias: f64,

