    child2_visits: f64,
    child3_visits: f64,

    // Beta posterior parameters (epistemic uncertainty)
    child0_alpha: f64,
    child0_beta: f64,
    child1_alpha: f64,
    child1_beta: f64,
    child2_alpha: f64,
    child2_beta: f64,
    child3_alpha: f64,
    child3_beta: f64,

    // Root value tracking
    value_sum: f64
}

// Game state
struct GameSt {
    position: f64,
    turn: f64,
    moves_left: f64
}

// Training example
struct TrainExample {
    position: f64,
    policy0: f64,
    policy1: f64,
    policy2: f64,
    policy3: f64,
    outcome: f64
}

// Provenance tracking for model updates
