    weights: NeuralWeights,
    // Provenance chain (last 4 updates for simplicity)
    prov0: ProvenanceEntry,
    prov1: ProvenanceEntry,
    prov2: ProvenanceEntry,
    prov3: ProvenanceEntry,
    num_updates: f64
}

// Training batch (fixed size for simplicity)
