    else if st.position < 0.-9.5 { 0.0 }
    else { 0.5 }
}

// =============================================================================
// MCTS with Neural Guidance
// =============================================================================

fn update_node_with_outcome(node: MctsNode, action: f64, outcome: f64) -> MctsNode {
