fn rhs(t: f64, y: [f64; 6]) -> [f64; 6] with Mut, Panic, Div {
    var dy: [f64; 6] = [0.0; 6]

    let cit_gut = y[0]
    let cit_pla = y[1]
    let bup_gut = y[2]
    let bup_pla = y[3]
    let cyp2d6_act = y[4]
    let cyp2c19_act = y[5]

