fn compute_field() with Mut {
    NONASSOC_COUNT = 0
    ASSOC_COUNT = 0
    TOTAL_TRIANGLES = 0
    var k = 0
    while k < 8 { HOLO_SPEC[k] = 0; k = k + 1 }

    var i = 0
    while i < 12 {
