let mut TX: [i64; 30] = [0; 30]
let mut TY: [i64; 30] = [0; 30]
let mut SX: [i64; 15] = [0; 15]
let mut SYC: [i64; 15] = [0; 15]
let mut N_TR: i64 = 0
let mut N_TE: i64 = 0

// ─── 2-layer E-KAN with variable width ───
// Max width=20: L1=1*20*6=120, L2=20*1*6=120 → 240 max
let mut EW: [i64; 240] = [0; 240]
let mut EH: [i64; 20] = [0; 20]

fn ew_set(i: i64, v: f64) with Mut { EW[i] = (v * 100000000.0) as i64 }
fn ew_get(i: i64) -> f64 with Div { (EW[i] as f64) / 100000000.0 }

fn ek_init(w: i64) with Mut, Div, Panic {
    let total = w * 6 + w * 6
    let mut i = 0
    while i < total { ew_set(i, rand_normal() * 0.08); i = i + 1 }
}

fn ek_fwd(x: f64, w: i64) -> f64 with Mut, Div {
    let mut j = 0
    while j < w {
        let mut s = 0.0
        let mut k = 0
        while k < 6 { s = s + ew_get(j * 6 + k) * hat6(x, k); k = k + 1 }
        EH[j] = (s * 100000000.0) as i64
        j = j + 1
    }
    let mut out = 0.0
    j = 0
    while j < w {
        let hv = (EH[j] as f64) / 100000000.0
        let mut hx = (hv + 1.5) / 3.0
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        let base = w * 6 + j * 6
        let mut k = 0
        while k < 6 { out = out + ew_get(base + k) * hat6(hx, k); k = k + 1 }
        j = j + 1
    }
    out
}

fn ek_gum(x: f64, w: i64, cs: f64) -> f64 with Mut, Div, Panic {
    let mut hvar: [f64; 20] = [0.0; 20]
    let mut j = 0
    while j < w {
        let mut v = 0.0
        let mut k = 0
        while k < 6 { let b = hat6(x, k); v = v + b * b * cs * cs; k = k + 1 }
        hvar[j] = v
        j = j + 1
    }
    let mut ov = 0.0
    j = 0
    while j < w {
        let hv = (EH[j] as f64) / 100000000.0
        let mut hx = (hv + 1.5) / 3.0
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        let mut v = 0.0
        let mut k = 0
        while k < 6 { let b = hat6(hx, k); v = v + b * b * cs * cs; k = k + 1 }
        ov = ov + v + hvar[j]
        j = j + 1
    }
    sqrt_v(ov)
}

fn ek_train(w: i64, lr: f64) with Mut, Div, Panic {
    let mut ep = 0
    while ep < 200 {
        let mut si = 0
        while si < N_TR {
            let x = (TX[si] as f64) / 100000000.0
            let err = ek_fwd(x, w) - (TY[si] as f64) / 100000000.0
            // L2 backprop
            let mut j = 0
            while j < w {
                let hv = (EH[j] as f64) / 100000000.0
                let mut hx = (hv + 1.5) / 3.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                let base = w * 6 + j * 6
                let mut k = 0
                while k < 6 {
                    let b = hat6(hx, k)
                    ew_set(base + k, ew_get(base + k) - lr * 2.0 * err * b)
                    k = k + 1
                }
                j = j + 1
            }
            // L1 backprop
            j = 0
            while j < w {
                let hv = (EH[j] as f64) / 100000000.0
                let mut hx = (hv + 1.5) / 3.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                let mut dh = 0.0
                let base = w * 6 + j * 6
                let mut k = 0
                while k < 6 { dh = dh + ew_get(base + k) * hat6(hx, k); k = k + 1 }
                let gh = 2.0 * err * dh
                k = 0
                while k < 6 {
                    let b = hat6(x, k)
                    ew_set(j * 6 + k, ew_get(j * 6 + k) - lr * gh * b)
                    k = k + 1
                }
                j = j + 1
            }
            si = si + 1
        }
        ep = ep + 1
    }
}

