    var out = 0.0
    j = 0
    while j < 10 {
        let hv = (EK_H[j] as f64) / 100000000.0
        var hx = (hv + 2.0) / 4.0
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        let base = 480 + j * 6
        var k = 0
        while k < 6 { out = out + ek_get(base + k) * hat6(hx, k); k = k + 1 }
        j = j + 1
    }
    out
