        j = j + 1;
    }
    var out_var = 0.0;
    j = 0;
    while j < 10 {
        let hv = (EK_H[j] as f64) / 100000000.0;
        var hx = (hv + 2.0) / 4.0;
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        var v = 0.0;
        var k = 0;
        while k < 6 { let b = hat6(hx, k); v = v + b * b * cs * cs; k = k + 1 }
        out_var = out_var + v + h_var[j];
        j = j + 1;
    }
    sqrt_c(out_var);
