            let l2b = n_in * n_h * 6
            let mut j = 0
            while j < n_h {
                let hv = (EH[j] as f64) / 100000000.0
                let mut hx = (hv + 2.0) / 4.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                let base = l2b + (j * n_out + 0) * 6
                let mut k = 0
                while k < 6 {
                    let b = hat6(hx, k)
