                // Update L1 weights
                k = 0
                while k < 10 {
                    let b = hat10(x, k)
                    let grad = grad_h * b
                    let w = ek_get(j * 10 + k)
                    ek_set(j * 10 + k, w - lr * grad)
                    k = k + 1
                }
                j = j + 1
            }

            si = si + 1
        }

        if epoch % 50 == 0 {
            let mse = total_loss / 80.0
            print("  epoch "); print_int(epoch); print(" MSE="); print(mse); print("\n")
        }
        epoch = epoch + 1
    }
}

