    let mut gum_c1 = 0
    let mut gum_c196 = 0
    let mut gum_c258 = 0
    let mut ens_c1 = 0
    let mut ens_c196 = 0
    let mut ens_c258 = 0
    let mut gum_sig_sum = 0.0
    let mut ens_sig_sum = 0.0

