// ─── RNG ───

var RNG_A: i64 = 0
var RNG_B: i64 = 0

fn rng_init() with Mut { RNG_A = 98765432; RNG_B = 12345678 }

fn rng_next() -> i64 with Mut {
    var x = RNG_A
    let y = RNG_B
    RNG_A = y
    x = x ^ (x << 23)
    x = x ^ (x >> 17)
    x = x ^ (y ^ (y >> 26))
    RNG_B = x
    let r = x + y
    if r < 0 { 0 - r } else { r }
}

fn rand_xavier(fan_in: i64, fan_out: i64) -> f64 with Mut, Div, Panic {
    let r = rng_next()
