    let action = select_action(node, c_puct, c_epistemic)

    // Apply action to get new state
    let nst = apply_action(st, action)

    // Evaluate (simple: use terminal value or heuristic)
    let value = if is_terminal(nst) > 0.5 {
        get_value(nst)
    } else {
