        let s2 = lcg(s1)
        s = lcg(s2)
        let z = bm_normal(s1, s2)
        x = x + theta * (mu - x) * dt + sigma * fr_sqrt(dt) * z
        if x < 0.0 { x = 0.0 }
        path[i as usize] = x
        i = i + 1
    }
    path
