fn j3o_trace(x: J3O) -> f64 { x.c[0] + x.c[1] + x.c[2] }

fn j3o_norm_sq(x: J3O) -> f64 with Mut {
    var s: f64 = 0.0
    var i: i32 = 0
    while i < 27 { s = s + x.c[i] * x.c[i]; i = i + 1 }
    s
}

fn j3o_add(x: J3O, y: J3O) -> J3O with Mut {
    var r = j3o_zero()
    var i: i32 = 0
    while i < 27 { r.c[i] = x.c[i] + y.c[i]; i = i + 1 }
    r
