                    let idx = i ^ j
                    let s = oct_sigma(i, j)
                    let sf = if s > 0 { 1.0 } else { -1.0 }
                    r[idx] = r[idx] + sf * a[i] * b[j]
                }
                j = j + 1
            }
        }
        i = i + 1
    }
    r
