    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & 3
    let b_lo = b & 3
    if a_hi == 0 && b_hi == 0 {
        if a_lo == 0 || b_lo == 0 { return 1 }
        let half2 = 2
