            basis_mul(i, 1, j, 1)
            let fwd_idx = RES_IDX
            let fwd_sgn = RES_SGN
            basis_mul(j, 1, i, 1)
            let rev_idx = RES_IDX
            let rev_sgn = RES_SGN
            if fwd_idx != rev_idx { anti_ok = 0 }
            if fwd_sgn != (0 - rev_sgn) { anti_ok = 0 }
            j = j + 1
        }
        i = i + 1
    }
    if anti_ok == 1 {
        print("  [PASS] Anticommutativity: ei*ej = -ej*ei\n")
        pass = pass + 1
    } else {
        print("  [FAIL] Anticommutativity\n")
        fail = fail + 1
    }

    // 2. Each ei² = -1
    var sq_ok = 1
    i = 1
    while i < 8 {
        basis_mul(i, 1, i, 1)
        if RES_IDX != 0 { sq_ok = 0 }
        if RES_SGN != (0 - 1) { sq_ok = 0 }
        i = i + 1
    }
    if sq_ok == 1 {
        print("  [PASS] ei² = -1 for all i=1..7\n")
        pass = pass + 1
    } else {
        print("  [FAIL] ei²\n")
        fail = fail + 1
    }

    // 3. Moufang identity (one form): (a·(b·a))·c = a·(b·(a·c))
    // Check for specific basis elements
    var moufang_ok = 1
