                basis_mul(i, 1, k, 1)
                let t3_idx = RES_IDX
                let t3_sgn = RES_SGN
                basis_mul(j, 1, t3_idx, t3_sgn)
                let t4_idx = RES_IDX
                let t4_sgn = RES_SGN
                basis_mul(i, 1, t4_idx, t4_sgn)
