//! Octonion Neural Network (OctNN) Example
//!
//! Demonstrates native Octonion support in Sounio.
//! Octonions are 8-dimensional hypercomplex numbers providing 8x parameter efficiency
//! and exceptional Lie group (G2) representations.
//!
//! References:
//! - "Deep Octonion Networks" (arXiv:1903.08478)
//! - "Octonion-valued neural networks" (arXiv:1601.01507)

// ============================================================================
// OCTONION TYPE (inline definition for standalone example)
// ============================================================================

struct Octonion {
    a: f32,  // real part;
    b: f32,  // i coefficient;
    c: f32,  // j coefficient;
    d: f32,  // k coefficient;
    e: f32,  // l coefficient;
    f: f32,  // il coefficient;
    g: f32,  // jl coefficient;
    h: f32,  // kl coefficient;
}

// Construct octonion from components
fn oct(a: f32, b: f32, c: f32, d: f32, e: f32, f: f32, g: f32, h: f32) -> Octonion {
    Octonion { a: a, b: b, c: c, d: d, e: e, f: f, g: g, h: h }
}

// Zero octonion
fn oct_zero() -> Octonion {
