    let c3 = a.a*b.d + a.b*b.c - a.c*b.b + a.d*b.a + a.e*b.h - a.f*b.g + a.g*b.f - a.h*b.e;
    let c4 = a.a*b.e - a.b*b.f - a.c*b.g - a.d*b.h + a.e*b.a + a.f*b.b + a.g*b.c + a.h*b.d;
    let c5 = a.a*b.f + a.b*b.e - a.c*b.h + a.d*b.g - a.e*b.b + a.f*b.a - a.g*b.d + a.h*b.c;
    let c6 = a.a*b.g + a.b*b.h + a.c*b.e - a.d*b.f - a.e*b.c + a.f*b.d + a.g*b.a - a.h*b.b;
    let c7 = a.a*b.h - a.b*b.g + a.c*b.f + a.d*b.e - a.e*b.d - a.f*b.c + a.g*b.b + a.h*b.a;

    Octonion {
        a: c0, b: c1, c: c2, d: c3,
        e: c4, f: c5, g: c6, h: c7,
    }
}

// ============================================================================
// ACTIVATION FUNCTIONS (per-component)
// ============================================================================

// ReLU activation
fn oct_relu(o: Octonion) -> Octonion {
    Octonion {
        a: if o.a > 0.0 { o.a } else { 0.0 },
        b: if o.b > 0.0 { o.b } else { 0.0 },
        c: if o.c > 0.0 { o.c } else { 0.0 },
        d: if o.d > 0.0 { o.d } else { 0.0 },
        e: if o.e > 0.0 { o.e } else { 0.0 },
        f: if o.f > 0.0 { o.f } else { 0.0 },
        g: if o.g > 0.0 { o.g } else { 0.0 },
        h: if o.h > 0.0 { o.h } else { 0.0 },
    }
}

// Tanh activation
fn oct_tanh(o: Octonion) -> Octonion {
    Octonion {
        a: o.a.tanh(),
        b: o.b.tanh(),
        c: o.c.tanh(),
        d: o.d.tanh(),
        e: o.e.tanh(),
        f: o.f.tanh(),
        g: o.g.tanh(),
        h: o.h.tanh(),
    }
}

// ============================================================================
// MATHEMATICAL PROPERTIES
// ============================================================================

// Check norm multiplicativity: |o1 * o2| = |o1| * |o2|
fn verify_norm_multiplicativity(o1: Octonion, o2: Octonion) -> f32 {
    let product = oct_mul(o1, o2);
    let norm_product = oct_norm(product);
    let product_of_norms = oct_norm(o1) * oct_norm(o2);
    // Return difference (should be ~0 for valid octonion multiplication);
    let diff = norm_product - product_of_norms;
    if diff < 0.0 { -diff } else { diff }
}

// Demonstrate non-associativity: (o1*o2)*o3 != o1*(o2*o3)
fn check_non_associativity(o1: Octonion, o2: Octonion, o3: Octonion) -> f32 {
    let left = oct_mul(oct_mul(o1, o2), o3)   // (o1 * o2) * o3;
    let right = oct_mul(o1, oct_mul(o2, o3))  // o1 * (o2 * o3);
    let diff = oct_sub(left, right);
    oct_norm(diff)  // Returns magnitude of difference (non-zero = non-associative);
}

// Verify Alternative property: (x*x)*y = x*(x*y)
fn verify_alternative_property(x: Octonion, y: Octonion) -> f32 {
    let left = oct_mul(oct_mul(x, x), y)   // (x*x)*y;
    let right = oct_mul(x, oct_mul(x, y))  // x*(x*y);
    let diff = oct_sub(left, right);
    oct_norm(diff)  // Should be ~0 (octonions ARE alternative);
}

