    let o = oct(1.0, -0.5, 0.8, -0.3, 0.6, -0.2, 0.4, -0.1);

    let o_relu = oct_relu(o);
    let o_tanh = oct_tanh(o);

    // ReLU: negative components become 0;
    // Tanh: all components in (-1, 1);

