// ═══════════════════════════════════════════════════════════════════════════
// G₂ Automorphisms of the Octonions
// ═══════════════════════════════════════════════════════════════════════════
//
// The automorphism group of the octonions is the exceptional Lie group G₂,
// the smallest of the 5 exceptional Lie groups (E₆, E₇, E₈, F₄, G₂).
// dim(G₂) = 14.
//
// An automorphism φ: O → O satisfies φ(xy) = φ(x)φ(y) for all x,y.
// For basis elements, this means:
//   φ(ei)·φ(ej) = φ(ei·ej)
//
// Key facts:
// - G₂ acts transitively on the unit sphere S⁶ in Im(O)
// - G₂ ⊂ SO(7): every automorphism is an orthogonal transformation
// - G₂ preserves the Fano plane structure
// - The stabilizer of any basis element is SU(3) (14-8+2=8=dim(SU(3)))
//
// We verify:
// 1. Fano plane permutations that preserve multiplication are automorphisms
// 2. Every automorphism preserves the inner product (G₂ ⊂ SO(7))
// 3. The number of Fano plane automorphisms = 168 = |PSL(2,7)|
// 4. Composition of automorphisms is closed (group property)
// ═══════════════════════════════════════════════════════════════════════════

let mut MULT: [i64; 64] = [0; 64]
let mut SIGN: [i64; 64] = [0; 64]

fn init_table() with Mut {
    let mut i = 0
    while i < 8 {
        MULT[0*8+i] = i; SIGN[0*8+i] = 1
        MULT[i*8+0] = i; SIGN[i*8+0] = 1
        i = i + 1
    }
    i = 1
    while i < 8 { MULT[i*8+i] = 0; SIGN[i*8+i] = 0-1; i = i + 1 }
    let mut FA: [i64; 7] = [1,2,3,4,5,6,7]
    let mut FB: [i64; 7] = [2,3,4,5,6,7,1]
    let mut FC: [i64; 7] = [4,5,6,7,1,2,3]
    let mut t = 0
    while t < 7 {
        let a = FA[t]; let b = FB[t]; let c = FC[t]
        MULT[a*8+b]=c; SIGN[a*8+b]=1; MULT[b*8+a]=c; SIGN[b*8+a]=0-1
        MULT[b*8+c]=a; SIGN[b*8+c]=1; MULT[c*8+b]=a; SIGN[c*8+b]=0-1
        MULT[c*8+a]=b; SIGN[c*8+a]=1; MULT[a*8+c]=b; SIGN[a*8+c]=0-1
        t = t + 1
    }
}

let mut RES_IDX: i64 = 0
let mut RES_SGN: i64 = 0
fn basis_mul(i_idx: i64, i_sgn: i64, j_idx: i64, j_sgn: i64) with Mut {
    RES_IDX = MULT[i_idx*8+j_idx]
    RES_SGN = i_sgn * j_sgn * SIGN[i_idx*8+j_idx]
