    i = 1
    while i < 8 { MULT[i*8+i] = 0; SIGN[i*8+i] = -1; i = i + 1 }
    var FA: [i64; 7] = [1,2,3,4,5,6,7]
    var FB: [i64; 7] = [2,3,4,5,6,7,1]
    var FC: [i64; 7] = [4,5,6,7,1,2,3]
    var t = 0
    while t < 7 {
        let a = FA[t]; let b = FB[t]; let c = FC[t]
        MULT[a*8+b]=c; SIGN[a*8+b]=1; MULT[b*8+a]=c; SIGN[b*8+a]=-1
        MULT[b*8+c]=a; SIGN[b*8+c]=1; MULT[c*8+b]=a; SIGN[c*8+b]=-1
        MULT[c*8+a]=b; SIGN[c*8+a]=1; MULT[a*8+c]=b; SIGN[a*8+c]=-1
