fn mlp2_forward(
    w1: Octonion, b1: Octonion,  // hidden layer;
    w2: Octonion, b2: Octonion,  // output layer;
    input: Octonion;
) -> Octonion {
    // Layer 1: hidden layer with ReLU;
    let h1 = neuron_forward(w1, b1, input);
    let h1_act = oct_relu(h1);

    // Layer 2: output layer (no activation);
    let out = neuron_forward(w2, b2, h1_act);
    out;
}

