// Demonstrates norm multiplicativity: |a * b| = |a| * |b|
fn demo_norm_multiplicativity() -> i32 {
    let o1 = oct(1.0, 0.5, 0.3, 0.2, 0.1, 0.15, 0.25, 0.05);
    let o2 = oct(0.5, 0.6, 0.4, 0.3, 0.2, 0.1, 0.1, 0.1);

    let product = oct_mul(o1, o2);
