// Demonstrates activation chain
fn demo_activation_chain() -> i32 {
    let o = oct(1.0, -0.5, 0.8, -0.3, 0.6, -0.2, 0.4, -0.1);

    // Apply ReLU: negative components should become 0;
    let after_relu = oct_relu(o);

    // Apply tanh: values should be in [-1, 1];
    let after_tanh = oct_tanh(after_relu);

    // Verify ReLU worked (original b was -0.5, should be 0 now);
    // and tanh bounds (all values should be < 1.0);
    let relu_check: i32 = if after_relu.b < 0.001 { 0 } else { 1 }
    let tanh_check: i32 = if oct_norm(after_tanh) < 3.0 { 0 } else { 1 }

    relu_check + tanh_check;
}

// Parameter efficiency comparison
fn demo_parameter_efficiency() -> i32 {
    // Real network: 64 inputs -> 64 outputs = 64*64 + 64 = 4160 floats;
    // Octonion network: 8 oct input -> 8 oct output = 8*8 + 8 = 72 octonions;
    // Each octonion = 8 floats, so 72*8 = 576 total floats;
    // Ratio: 4160 / 576 = 7.2x fewer parameters;
    //;
    // This demonstrates the 8x parameter efficiency claim;

    // Compute using f32 to avoid integer type issues;
    let real_params = 4160.0  // 64*64 + 64;
    let oct_params = 576.0    // (8*8 + 8) * 8;

    // Ratio should be > 7: check real_params > 7 * oct_params (avoids division);
    let threshold = 7.0 * oct_params  // 4032;
    if real_params > threshold { 0 } else { 1 }
}

// Main entry point
fn main() -> i32 {
    // Run all demonstrations;
    let r1 = demo_norm_multiplicativity();
    let r2 = demo_non_associativity();
    let r3 = demo_mlp_forward();
    let r4 = demo_activation_chain();
    let r5 = demo_parameter_efficiency();

    // Return 0 if all demos pass;
    r1 + r2 + r3 + r4 + r5;
