    // There are 7 such triples. All other triples are non-associative.
    var assoc_count = 0
    var nonassoc_count = 0

    var i = 1
    while i < 8 {
        var j = 1
        while j < 8 {
            if j != i {
                var k = 1
                while k < 8 {
                    if k != i {
                        if k != j {
                            basis_mul(i, 1, j, 1)
                            let ab_idx = RES_IDX
                            let ab_sgn = RES_SGN
                            basis_mul(ab_idx, ab_sgn, k, 1)
                            let l_idx = RES_IDX
                            let l_sgn = RES_SGN

