    let t2_sgn = RES_SGN
    basis_mul(t2_idx, t2_sgn, 7, 1)
    let t3_idx = RES_IDX
    let t3_sgn = RES_SGN
    basis_mul(t3_idx, t3_sgn, 6, 1)
    let c2_idx = RES_IDX
    let c2_sgn = RES_SGN

