    ok
}

// ─── Test 3: Two points determine a unique line ───
fn test_two_points_line() -> i64 with Mut, IO {
    // Line through P_i, P_j is L_ij = I - P_i - P_j = P_k (the third point)
    // This point-line duality is a defining property of OP²

    var ok = 1
    // L12 = I - P1 - P2 = diag(1,1,1) - diag(1,0,0) - diag(0,1,0) = diag(0,0,1) = P3
    var k = 0
    while k < 3 {
        let l12 = 1 - get_p(1, k) - get_p(2, k)
        if l12 != get_p(3, k) { ok = 0 }
        k = k + 1
    }

