    k = 0
    while k < 3 {
        let l23 = 1 - get_p(2, k) - get_p(3, k)
        if l23 != get_p(1, k) { ok = 0 }
        k = k + 1
    }

    if ok == 1 {
        print("  [PASS] Two points determine a unique line (L_ij = I - P_i - P_j)\n")
        print("         Point-line duality: each line IS the complementary point\n")
    } else {
        print("  [FAIL] Two points line\n")
    }
    ok
}

