// ─── Test 9: O-SSM collinearity constraint ───
fn test_ossm_collinearity() -> i64 with Mut, IO {
    // Verify triangle incidence: point P on line L iff Tr(P*L) = 0
    // L12 = P3, L13 = P2, L23 = P1 (by point-line duality)
    var incidence_ok = 1

    // Tr(P1*P3) = 0: P1 is on line L12=P3
    var tr = 0
    var k = 0
    while k < 3 {
        tr = tr + get_p(1, k) * get_p(3, k)
        k = k + 1
    }
