// ═══════════════════════════════════════════════════════════════════════════
// Octonion State Space Model (O-SSM)
// ═══════════════════════════════════════════════════════════════════════════
//
// h_t = sigmoid(A ⊗ h_{t-1} + B · x_t)
// y_t = Re(C ⊗ h_t)
//
// State dynamics in O (8D). One octonion multiply = 7 coupled rotations.
// The associator [A,h,Bx] = (A⊗h)⊗(Bx) - A⊗(h⊗Bx) is a free geometric
// signal that real-valued SSMs cannot produce.
//
// GUM uncertainty through every operation. First O-SSM ever built.

// ─── Math ───
fn sqrt_o(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}
fn abs_o(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }
fn exp_o(x: f64) -> f64 with Mut, Div, Panic {
    if x > 20.0 { return exp_o(10.0) * exp_o(x - 10.0) }
    if x < 0.0 - 20.0 { return 0.0 }
    var s = 1.0
    var t = 1.0
    var i = 1
    while i <= 20 { t = t * x / (i as f64); s = s + t; i = i + 1 }
    s
}
fn sigmoid_o(x: f64) -> f64 with Mut, Div, Panic { 1.0 / (1.0 + exp_o(0.0 - x)) }

var RNG_O: i64 = 271828
fn rand_o() -> f64 with Mut, Div, Panic {
    RNG_O = (RNG_O * 6364136223846793005 + 1442695040888963407)
    var v = RNG_O
    if v < 0 { v = 0 - v }
