}

fn high_accuracy_config() -> ODEConfig {
    return ODEConfig {
        rtol: 0.0000000001,
        atol: 0.000000000001,
        dt_init: 0.0,
        dt_min: 0.000000000000001,
        dt_max: 1.0,
        max_steps: 10000000,
        safety: 0.9,
        max_growth: 5.0,
        min_shrink: 0.1
    }
}

// ============================================================================
// SOLUTION STRUCTURE
// ============================================================================

struct ODESolution {
    success: bool,
    nsteps: i64,
    nfeval: i64,
    nreject: i64,
    t_final: f64,
    u_final: f64
}

// ============================================================================
// TSIT5 SOLVER (Tsitouras 5(4))
// ============================================================================

// Stage times
fn c2() -> f64 { return 0.161 }
fn c3() -> f64 { return 0.327 }
fn c4() -> f64 { return 0.9 }
fn c5() -> f64 { return 0.9800255409045097 }
