    // scale_2 = sqrt(2 / (4+2)) = sqrt(1/3) ≈ 0.577

    let s = 0.5  // slightly smaller scale for stability

    // Hidden layer weights - slightly varied to encourage learning
    let w1 = make_octonion(
        0.5*s,   0.1*s,   0.2*s,   0.15*s,   0.3*s,   0.05*s,   0.25*s,   0.1*s
