// Forward pass through the network
fn network_forward(net: &RotationNetwork, input: Octonion) -> Octonion {
    // Hidden layer with G2-equivariant activation
    let hidden = oct_linear_forward(net.w1, net.b1, input)
    let hidden_act = oct_relu(hidden)

    // Output layer (no activation - let loss handle normalization)
    let output = oct_linear_forward(net.w2, net.b2, hidden_act)
