        if o.s > 0.0 { o.s } else { alpha * o.s }
    )
}

// Clamp helper: restrict value to [0, 1] range
fn clamp_01(val: f32) -> f32 {
    if val < 0.0 { 0.0 } else { if val > 1.0 { 1.0 } else { val } }
}

// Component-wise linear approximation to sigmoid: 0.5 + 0.125*x
// Clipped to [0, 1] range for stability
fn oct_sigmoid_approx(o: Octonion) -> Octonion {
    let w = clamp_01(0.5 + 0.125 * o.w)
    let x = clamp_01(0.5 + 0.125 * o.x)
    let y = clamp_01(0.5 + 0.125 * o.y)
    let z = clamp_01(0.5 + 0.125 * o.z)
    let t = clamp_01(0.5 + 0.125 * o.t)
    let u = clamp_01(0.5 + 0.125 * o.u)
    let v = clamp_01(0.5 + 0.125 * o.v)
    let s = clamp_01(0.5 + 0.125 * o.s)

    make_octonion(w, x, y, z, t, u, v, s)
}

// GELU approximation: x * sigmoid(1.702*x)
fn oct_gelu_approx(o: Octonion) -> Octonion {
    let scaled = oct_scale(o, 1.702)
    let sigmoid_part = oct_sigmoid_approx(scaled)
    // Component-wise multiplication with activation
    make_octonion(
        o.w * sigmoid_part.w, o.x * sigmoid_part.x, o.y * sigmoid_part.y, o.z * sigmoid_part.z,
        o.t * sigmoid_part.t, o.u * sigmoid_part.u, o.v * sigmoid_part.v, o.s * sigmoid_part.s
    )
}

// ============================================================================
// NEURAL NETWORK LAYERS
// ============================================================================

// Octonion linear layer: y = w * x + b
fn oct_linear_forward(weight: Octonion, bias: Octonion, input: Octonion) -> Octonion {
    let weighted = oct_mul(weight, input)
    oct_add(weighted, bias)
}

// Process a batch of predictions (simplified for single forward pass)
// For full batch processing, would need dynamic array support
fn process_batch_prediction(
    weight: Octonion,
    bias: Octonion,
    input: Octonion
) -> Octonion {
    oct_linear_forward(weight, bias, input)
}

// ============================================================================
