// Mean Squared Error loss between prediction and target
fn oct_mse_loss(pred: Octonion, target: Octonion) -> f32 {
    let diff = oct_sub(pred, target)
    oct_dot(diff, diff)
}

// MSE loss for pair of predictions (simplified for single step)
fn oct_pair_mse_loss(pred1: Octonion, target1: Octonion, pred2: Octonion, target2: Octonion) -> f32 with Panic {
    let loss1 = oct_mse_loss(pred1, target1)
    let loss2 = oct_mse_loss(pred2, target2)
    (loss1 + loss2) / 2.0
}

// ============================================================================
// SIMPLE NETWORK: Input -> Hidden -> Output
// ============================================================================

// Network structure for predicting rotation output from rotation input
struct RotationNetwork {
    // Input to hidden: single weight and bias for simplicity
    w1: Octonion,
    b1: Octonion,

    // Hidden to output: single weight and bias
    w2: Octonion,
    b2: Octonion,
}

// Initialize network with small random-like weights
fn init_rotation_network() -> RotationNetwork {
    // Xavier initialization: scale = sqrt(2 / (input + output))
    // For octonions: input=2, hidden=4, output=2
    // scale_1 = sqrt(2 / (2+4)) = sqrt(1/3) ≈ 0.577
    // scale_2 = sqrt(2 / (4+2)) = sqrt(1/3) ≈ 0.577

    let s = 0.5  // slightly smaller scale for stability

    // Hidden layer weights - slightly varied to encourage learning
    let w1 = make_octonion(
        0.5*s,   0.1*s,   0.2*s,   0.15*s,   0.3*s,   0.05*s,   0.25*s,   0.1*s
    )
    let b1 = make_octonion(
        0.01,   0.005,   0.01,   0.005,   0.01,   0.005,   0.01,   0.005
    )

    // Output layer weights
    let w2 = make_octonion(
        0.4*s,   0.15*s,   0.25*s,   0.1*s,   0.2*s,   0.12*s,   0.18*s,   0.08*s
    )
    let b2 = make_octonion(
        0.01,   0.005,   0.01,   0.005,   0.01,   0.005,   0.01,   0.005
    )

    RotationNetwork {
        w1: w1,
        b1: b1,
        w2: w2,
        b2: b2,
    }
}

// Forward pass through the network
fn network_forward(net: &RotationNetwork, input: Octonion) -> Octonion {
    // Hidden layer with G2-equivariant activation
    let hidden = oct_linear_forward(net.w1, net.b1, input)
    let hidden_act = oct_relu(hidden)

    // Output layer (no activation - let loss handle normalization)
    let output = oct_linear_forward(net.w2, net.b2, hidden_act)
    output
}

// ============================================================================
// TRAINING DEMONSTRATION
// ============================================================================

// Simple training step (without actual gradient computation)
// In production, this would use backpropagation via autodiff
fn training_step(
    net: &!RotationNetwork,
    input: Octonion,
    target: Octonion,
    learning_rate: f32
) -> f32 {
    // Forward pass
    let prediction = network_forward(net, input)

    // Compute loss
    let loss = oct_mse_loss(prediction, target)

    // For demonstration: simple weight update (not true gradient)
    // In real training, would use backprop to compute gradients
    let lr = learning_rate * 0.001

    // Minimal adjustment to weights for demonstration
    net.w1 = oct_scale(net.w1, 1.0 - 0.0001)
    net.w2 = oct_scale(net.w2, 1.0 - 0.0001)

    loss
}

// ============================================================================
