// ============================================================================

// Validate network on a single example
fn validate_single(net: &RotationNetwork, input: Octonion, expected: Octonion) -> i32 with Panic {
    let prediction = network_forward(net, input)
    let error = oct_sub(prediction, expected)
    let error_norm = oct_norm(error)

    // Return 0 if prediction is reasonable (error < threshold)
    if error_norm < 10.0 { 0 } else { 1 }
}

// Test parameter efficiency
fn check_parameter_efficiency() -> i32 with Panic {
    // Network structure:
    // - Input: 2 octonions = 16 floats
    // - Hidden: 4 octonions = 32 floats
    // - Output: 2 octonions = 16 floats
    // - Weights: 2 (w1, w2) + 2 (b1, b2) = 4 octonions = 32 floats
    // - Total: 32 floats = 32 floats semantic

    // Equivalent float32 network with same capacity:
    // - Input: 16 floats -> 32 hidden -> 16 output
    // - Weights: 16*32 + 32*16 + 32 + 16 = 512 + 512 + 48 = 1072 floats
    // - Compression: 1072 / 32 = 33.5x

    let semantic_params = 32.0
    let float_params = 1072.0
    let ratio = float_params / semantic_params  // ~33.5

    // Check if compression is > 20x
    if ratio > 20.0 { 0 } else { 1 }
}

