fn main() -> i32 with Panic {
    // Test 1: Parameter efficiency
    let test1 = check_parameter_efficiency()

    // Test 2: Initialize and forward pass
    let net = init_rotation_network()

    // Create test rotation (unit octonion)
    let input_rot = make_octonion(1.0, 0.1, 0.05, 0.05, 0.0, 0.0, 0.0, 0.0)
    let target_rot = make_octonion(0.95, 0.2, 0.1, 0.1, 0.05, 0.0, 0.0, 0.0)

