    let product = oct_mul(o1, o2)
    let norm_product = oct_norm(product)
    let product_norms = oct_norm(o1) * oct_norm(o2)
    let norm_diff = norm_product - product_norms
    let abs_diff = if norm_diff < 0.0 { -norm_diff } else { norm_diff }
    let test3 = if abs_diff < 0.1 { 0 } else { 1 }

