    // The triple {i,j,k} forms a quaternion subalgebra
    // Count unique unordered triples
    let mut triples: [i64; 21] = [0; 21]  // store as i*64+j*8+k, unique
    let mut count = 0

    let mut i = 1
    while i < 8 {
        let mut j = i + 1
        while j < 8 {
