            let k = RES_IDX
            if k > 0 {
                // Normalize: sort triple
                let mut a = i
                let mut b = j
                let mut c = k
                // Simple sort of 3
                if b < a { let tmp = a; a = b; b = tmp }
                if c < b { let tmp2 = b; b = c; c = tmp2 }
                if b < a { let tmp3 = a; a = b; b = tmp3 }

                let code = a * 64 + b * 8 + c
                // Check if already seen
                let mut seen = 0
                let mut ci = 0
                while ci < count {
                    if triples[ci] == code { seen = 1 }
                    ci = ci + 1
                }
                if seen == 0 {
                    triples[count] = code
                    count = count + 1
                }
