        v = v + 1
    }
}

fn nt_get_pred() -> i64 with Div {
    var best = 0
    var bv = (NTL[0] as f64) / 100000000.0
    var i = 1
    while i < 8 {
        let v = (NTL[i] as f64) / 100000000.0
        if v > bv { bv = v; best = i }
        i = i + 1
    }
    best
}

