        var d = 0
        while d < 32 { sab[d] = H[d]; d = d + 1 }
        reset_mh_h()
        mh_step(b)
        mh_step(a)
        var dist = 0.0
        d = 0
        while d < 32 {
            let diff = ((sab[d] - H[d]) as f64) / 100000000.0
            dist = dist + diff * diff
            d = d + 1
        }
        total = total + sqrt_q(dist)
        trial = trial + 1
    }
    total / 8.0
}

