}

// ═══════════════════════════════════════════════════════════════════════════
// Order Sensitivity: L2 distance between states for [A,B] vs [B,A]
// ═══════════════════════════════════════════════════════════════════════════

fn measure_order_mh() -> f64 with Mut, Div, Panic {
    var total = 0.0
    var trial = 0
    while trial < 8 {
        let a = (rng_next() / 100) % 8
        let b = (rng_next() / 100) % 8
        reset_mh_h()
        mh_step(a)
        mh_step(b)
        // Save state
        var sab: [i64; 32] = [0; 32]
        var d = 0
        while d < 32 { sab[d] = H[d]; d = d + 1 }
        reset_mh_h()
        mh_step(b)
        mh_step(a)
        var dist = 0.0
        d = 0
        while d < 32 {
            let diff = ((sab[d] - H[d]) as f64) / 100000000.0
            dist = dist + diff * diff
            d = d + 1
        }
        total = total + sqrt_q(dist)
        trial = trial + 1
    }
    total / 8.0
}

fn measure_order_diag() -> f64 with Mut, Div, Panic {
    var total = 0.0
    var trial = 0
    while trial < 8 {
        let a = (rng_next() / 100) % 8
        let b = (rng_next() / 100) % 8
        reset_diag_h()
        diag_step(a)
        diag_step(b)
        var sab: [i64; 32] = [0; 32]
        var d = 0
        while d < 32 { sab[d] = DH[d]; d = d + 1 }
        reset_diag_h()
        diag_step(b)
        diag_step(a)
        var dist = 0.0
        d = 0
        while d < 32 {
            let diff = ((sab[d] - DH[d]) as f64) / 100000000.0
            dist = dist + diff * diff
            d = d + 1
        }
        total = total + sqrt_q(dist)
        trial = trial + 1
    }
    total / 8.0
}

