            j = j + 1
        }
        s = s + wg(128 + d) * wg(token * 8 + d)
        if s > 4.0 { s = 4.0 }
        if s < 0.0 - 4.0 { s = 0.0 - 4.0 }
        hs(d, s)
        d = d + 1
    }
    // Output logits
    var v = 0
    while v < 8 {
        var s = 0.0
        d = 0
