// Simplified PBPK-style one-compartment demo with uncertainty fields.

struct KnowledgeF64 {
    value: f64,
    uncertainty: f64
}

fn concentration(dose_mg: KnowledgeF64, volume_l: KnowledgeF64) -> KnowledgeF64 {
    let c = dose_mg.value / volume_l.value

    // First-order linearized uncertainty for division:
    // dc ≈ |∂c/∂dose| u_dose + |∂c/∂vol| u_vol
    let d_cdose = 1.0 / volume_l.value
    let d_cvol = -dose_mg.value / (volume_l.value * volume_l.value)

    let u = (if d_cdose < 0.0 { -d_cdose } else { d_cdose }) * dose_mg.uncertainty
          + (if d_cvol < 0.0 { -d_cvol } else { d_cvol }) * volume_l.uncertainty

    return KnowledgeF64 {
        value: c,
        uncertainty: u
    }
}

fn main() {
    let dose = KnowledgeF64 {
        value: 500.0,
        uncertainty: 5.0
    }

    let volume = KnowledgeF64 {
        value: 42.0,
        uncertainty: 0.8
    }

    let c0 = concentration(dose, volume)

    println("example: pbpk_simple")
    println("C0 (mg/L)")
    println(c0.value)
    println("C0 uncertainty")
    println(c0.uncertainty)
}

