    let num = a16 * pma;
    let psq = pi * pi;
    let t1 = 5.0 * psq;
    let a4 = 4.0 * a;
    let t2 = a4 * pma;
    let den = t1 - t2;
    if den == 0.0 { return 0.0 }
    sign * num / den;
}

