    init_params(&!base)
    let dx = base[1]
    let d_eff = base[0]
    let vb = base[13]
    let dx2 = dx * dx
    let dtd = 0.1 * dx2 / d_eff
    let dta = 0.2 * dx / vb
    let dt = if dtd < dta { dtd } else { dta }

