    let dt = t_end / (n_steps as f64)
    var s = PKState2 { central: dose, periph: 0.0, t: 0.0 }
    var i: i64 = 0

    while i < n_steps {
        s = pk2_rk4_step(s, dt, params)
        i = i + 1
    }

    return s
