fn pk2_rk4_step(s: PKState2, dt: f64, p: PKParams2) -> PKState2 {
    let k1 = pk2_ode(s, p);

    let s2 = PKState2 {
        central: s.central + 0.5 * dt * k1.d_central,
        periph: s.periph + 0.5 * dt * k1.d_periph,
        t: s.t + 0.5 * dt;
