    let pred3 = Emax * obs_c3 / (EC50 + obs_c3);

    let err1 = pred1 - obs_e1;
    let err2 = pred2 - obs_e2;
    let err3 = pred3 - obs_e3;

    return err1 * err1 + err2 * err2 + err3 * err3;
