        tile.sync();

        // Matrix multiply-accumulate using Tensor Cores;
        // On Blackwell: WGMMA (warpgroup MMA);
        // On Ampere/Hopper: MMA (warp-scoped);
        c_tile = tile.mma(c_tile, a_tile, b_tile);

        // Synchronize before next iteration;
        tile.sync();
