fn ln_f64(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 - 1000000.0 }
    var m = x
    var k: i64 = 0
    while m >= 2.0 { m = m / 2.0; k = k + 1 }
    while m < 1.0 { m = m * 2.0; k = k - 1 }
    let y = m - 1.0
    let ln_m = y - y*y/2.0 + y*y*y/3.0 - y*y*y*y/4.0
    var kf = 0.0
    var j: i64 = 0
    if k > 0 { while j < k { kf = kf + 1.0; j = j + 1 } }
    if k < 0 { while j > k { kf = kf - 1.0; j = j - 1 } }
    return ln_m + kf * 0.693147180559945
