    // Measure a resistor
    let resistance = Uncertain { mean: 100.0, std: 2.5 };  // 100 ± 2.5 Ω
    let voltage = Uncertain { mean: 5.0, std: 0.1 };       // 5 ± 0.1 V

    print("Resistance: {} ± {} Ω", resistance.mean, resistance.std);
    print("Voltage: {} ± {} V", voltage.mean, voltage.std);

    // Ohm's law: I = V / R
    let current = divide_uncertain(voltage, resistance);

    print("\nOhm's Law: I = V / R");
    print("Current: {:.4} ± {:.4} A", current.mean, current.std);

    // Power dissipation: P = V * I = V² / R
    let power = multiply_uncertain(voltage, current);

    print("\nPower dissipation: P = V × I");
    print("Power: {:.3} ± {:.3} W", power.mean, power.std);

    // Relative uncertainty
    let voltage_rel_unc = voltage.std / voltage.mean;
    let resistance_rel_unc = resistance.std / resistance.mean;
    let current_rel_unc = current.std / current.mean;

    print("\n=== Relative Uncertainty ===");
    print("Voltage uncertainty: {:.2}%", voltage_rel_unc * 100.0);
    print("Resistance uncertainty: {:.2}%", resistance_rel_unc * 100.0);
    print("Current uncertainty: {:.2}%", current_rel_unc * 100.0);

    // Temperature measurement
    print("\n=== Temperature Measurement ===");
    let temp_celsius = Uncertain { mean: 25.0, std: 0.5 };
    print("Temperature: {} ± {} °C", temp_celsius.mean, temp_celsius.std);

